#!/usr/bin/env bash
# test-skill.sh — Regression suite for the sso-single-branch-development hooks bundle.
#
# Tests: track-preflight, track-reconcile, track-guard, track-evidence (producer),
#        track-evidence-gate, track-meter, track-trace, track-report, track-sentinel,
#        track-notify, track-deps (version-lock + probe cache), structural integrity.
#        Includes a producer->gate end-to-end contract
#        so the evidence record is generated by track-evidence.sh, never hand-written.
#        15 suites · 284 total · 284 passed · 0 failed · 0 skipped (2026-08-07)
#
# Scope: the MECHANICAL gates only. The judgement gates this skill deliberately leaves to
# the prompt (TDD ordering, maker/checker split, governance content actually reaching a
# subagent brief) cannot be asserted here — audit those against tests/prompt-level-checklist.md.
# Run automatically on every push/PR by .github/workflows/skill-tests.yml.
#
# Usage:
#   bash .github/skills/sso-single-branch-development/tests/test-skill.sh
#   bash tests/test-skill.sh          # from inside sso-single-branch-development/ dir
#
# Requirements: bash, jq, git (gh auth bypassed via PREFLIGHT_REQUIRE_GH=0).
# Side-effects: temp branch + temp runs/ dir; cleaned up on exit.
# Exit: 0 = all passed, 1 = one or more failures.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRIPTS_DIR="$SCRIPT_DIR/../scripts"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"
cd "$REPO_ROOT"

GUARD="$SCRIPTS_DIR/track-guard.sh"
PREFLIGHT="$SCRIPTS_DIR/track-preflight.sh"
RECONCILE="$SCRIPTS_DIR/track-reconcile.sh"
EVIDENCE="$SCRIPTS_DIR/track-evidence.sh"
EVIDENCE_GATE="$SCRIPTS_DIR/track-evidence-gate.sh"
METER="$SCRIPTS_DIR/track-meter.sh"
TRACE="$SCRIPTS_DIR/track-trace.sh"
NOTE="$SCRIPTS_DIR/track-note.sh"
SENTINEL="$SCRIPTS_DIR/track-sentinel.sh"
NOTIFY="$SCRIPTS_DIR/track-notify.sh"
TOKENS="$SCRIPTS_DIR/track-tokens.sh"
AUDIT="$SCRIPTS_DIR/track-audit.sh"
DEPS="$SCRIPTS_DIR/track-deps.sh"
for s in "$GUARD" "$PREFLIGHT" "$RECONCILE" "$EVIDENCE" "$EVIDENCE_GATE" \
         "$METER" "$TRACE" "$NOTE" "$SENTINEL" "$NOTIFY" "$TOKENS" "$AUDIT" "$DEPS"; do
  [ -x "$s" ] || chmod +x "$s"
done
INSTALL_HOOKS="$SCRIPTS_DIR/install-hooks.sh"
[ -x "$INSTALL_HOOKS" ] || chmod +x "$INSTALL_HOOKS"

# ---------------------------------------------------------------------------
# Harness
# ---------------------------------------------------------------------------
PASS=0; FAIL=0; SKIP=0; FAILURES=""
pass() { PASS=$((PASS+1)); printf '  OK    %s\n' "$1"; }
fail() { FAIL=$((FAIL+1)); printf '  FAIL  %s\n' "$1"; FAILURES="$FAILURES\n  - $1"; }
skip() { SKIP=$((SKIP+1)); printf '  SKIP  %s\n' "$1"; }
section() { printf '\n--- %s ---\n' "$1"; }

assert_deny() {
  local desc="$1" hook="$2" json="$3"; shift 3
  local result
  result=$(printf '%s' "$json" | env "$@" bash "$hook" 2>&1) || true
  if printf '%s' "$result" | grep -qE '"deny"|"block"'; then pass "$desc"
  else fail "$desc (got: $(printf '%s' "$result" | head -c 120))"; fi
}
assert_allow() {
  local desc="$1" hook="$2" json="$3"; shift 3
  local result
  result=$(printf '%s' "$json" | env "$@" bash "$hook" 2>&1) || true
  if printf '%s' "$result" | grep -qE '"deny"|"block"'; then
    fail "$desc (expected allow, got: $(printf '%s' "$result" | head -c 120))"
  else pass "$desc"; fi
}

# ---------------------------------------------------------------------------
# Temp state
# ---------------------------------------------------------------------------
TMPDIR_RUNS="$(mktemp -d)"
ORIG_BRANCH="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo detached)"
TEST_BRANCH="test/sbd-skill-$(date +%s)"
SCRATCH_FILES=()
RUN1_ID=""

cleanup() {
  git checkout "$ORIG_BRANCH" --quiet 2>/dev/null || true
  git branch -D "$TEST_BRANCH" --quiet 2>/dev/null || true
  for f in "${SCRATCH_FILES[@]:-}"; do
    git rm --cached "$f" --quiet 2>/dev/null || true; rm -f "$f"; done
  rm -rf "$TMPDIR_RUNS" ${AUD_DIFF_ISO:+"$AUD_DIFF_ISO"}
}
trap cleanup EXIT
git checkout -b "$TEST_BRANCH" --quiet 2>/dev/null

# Fingerprint matching evidence-gate/evidence exactly (HEAD + diff + untracked)
current_fingerprint() {
  local hc; command -v shasum >/dev/null 2>&1 && hc=shasum || hc=sha1sum
  { git rev-parse HEAD 2>/dev/null || echo no-head
    git diff HEAD 2>/dev/null || true
    local u; u="$(git ls-files --others --exclude-standard 2>/dev/null || true)"
    if [ -n "$u" ]; then
      printf '%s\n' "$u"; printf '%s\n' "$u" | git hash-object --stdin-paths 2>/dev/null || true
    fi
  } | $hc | cut -d' ' -f1
}

# NOTE: REPO_ROOT above is the bundle's .github/ dir, NOT the git worktree root. The guard
# resolves every path against the WORKTREE root (TRACK_ALLOWED_PREFIXES is documented as
# workspace-relative), so guard fixtures must be built from the real toplevel — anchoring
# them to $PWD instead only ever passed because the guard used to strip $PWD too, which is
# the CWD-sensitivity bug itself.
GIT_TOP="$(git rev-parse --show-toplevel 2>/dev/null || printf '%s' "$REPO_ROOT")"
ABS="${GIT_TOP}/"

# ---------------------------------------------------------------------------
# SUITE 1 -- track-preflight.sh
# ---------------------------------------------------------------------------
section "track-preflight.sh"

result=$(TRACK_ID=tst-setup TASKS="T001-T005" TRACK_BASE_REF=main \
         PREFLIGHT_REQUIRE_GH=0 RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>&1)
if printf '%s' "$result" | grep -q '"mode":"start"'; then
  pass "preflight: fresh start -> mode=start + RUN_ID minted"
  RUN1_ID=$(printf '%s' "$result" | grep -o '"run_id":"[^"]*"' | cut -d'"' -f4)
else fail "preflight: fresh start -> mode=start + RUN_ID minted"; fi

TRACK_ID=tst-setup TASKS="T001-T005" TRACK_BASE_REF=main \
PREFLIGHT_REQUIRE_GH=0 RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --commit >/dev/null 2>&1
ls "$TMPDIR_RUNS"/*.dispatch >/dev/null 2>&1 \
  && pass "preflight: --commit (deprecated alias) persists .dispatch breadcrumb" \
  || fail "preflight: --commit (deprecated alias) persists .dispatch breadcrumb"

# --persist is the primary flag name; it must behave identically to the --commit alias
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-persist TASKS="T001-T005" TRACK_BASE_REF=main \
PREFLIGHT_REQUIRE_GH=0 RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --persist >/dev/null 2>&1
ls "$TMPDIR_RUNS"/*tst-persist*.dispatch >/dev/null 2>&1 \
  && pass "preflight: --persist persists .dispatch breadcrumb" \
  || fail "preflight: --persist persists .dispatch breadcrumb"
rm -f "$TMPDIR_RUNS"/*.dispatch

# breadcrumb records the confirmed scope/toolchain/floor, not just identity
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-stamp TASKS="T001" TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  TRACK_ALLOWED_PREFIXES="backend-go/:frontend/" PREFLIGHT_REQUIRE_TOOLCHAIN="git,jq" \
  TRACK_REQUIRED_EVIDENCE="go-test,py" RUNS_DIR="$TMPDIR_RUNS" \
  bash "$PREFLIGHT" --commit >/dev/null 2>&1
stamp_file=$(ls "$TMPDIR_RUNS"/*tst-stamp*.dispatch 2>/dev/null | head -1)
if [ -n "$stamp_file" ] && jq -e '(.allowed_prefixes | index("backend-go/") != null) and .scope_set == true and (.require_toolchain | index("jq") != null) and (.required_evidence | index("go-test") != null) and .evidence_floor_set == true' "$stamp_file" >/dev/null 2>&1; then
  pass "preflight: --commit stamps confirmed scope/toolchain/floor into breadcrumb"
else
  fail "preflight: --commit stamps confirmed scope/toolchain/floor into breadcrumb"
fi

# --- confirm waiver (--yes / AUTO_CONFIRM) -------------------------------------
# The SBD confirm is a HUMAN gate. A worker dispatched by sso-executing-parallel-tracks has
# no human, so without an explicit waiver it either hangs or self-approves. These pin the
# contract: waived only when asked, always recorded, and never able to waive a prereq.
result=$(TRACK_ID=tst-confirm TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.auto_confirm == false and .confirm_required == true' >/dev/null 2>&1 \
  && pass "preflight: default -> confirm REQUIRED (auto_confirm false)" \
  || fail "preflight: default -> confirm REQUIRED (auto_confirm false)"

result=$(TRACK_ID=tst-confirm TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --yes 2>/dev/null)
printf '%s' "$result" | jq -e '.auto_confirm == true and .confirm_required == false' >/dev/null 2>&1 \
  && pass "preflight: --yes -> confirm waived" \
  || fail "preflight: --yes -> confirm waived"

result=$(TRACK_ID=tst-confirm TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 AUTO_CONFIRM=1 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.auto_confirm == true' >/dev/null 2>&1 \
  && pass "preflight: AUTO_CONFIRM=1 env -> confirm waived" \
  || fail "preflight: AUTO_CONFIRM=1 env -> confirm waived"

# The waiver must be AUDITABLE — a reader has to be able to tell a human-approved run
# from a wave-waived one long after the session is gone.
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-waived TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --persist --yes >/dev/null 2>&1
waived_file=$(ls "$TMPDIR_RUNS"/*tst-waived*.dispatch 2>/dev/null | head -1)
if [ -n "$waived_file" ] && jq -e '.auto_confirm == true and .confirmed_by == "orchestrator-waiver"' "$waived_file" >/dev/null 2>&1; then
  pass "preflight: --persist --yes records the waiver in the breadcrumb"
else
  fail "preflight: --persist --yes records the waiver in the breadcrumb"
fi
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-human TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --persist >/dev/null 2>&1
human_file=$(ls "$TMPDIR_RUNS"/*tst-human*.dispatch 2>/dev/null | head -1)
if [ -n "$human_file" ] && jq -e '.auto_confirm == false and .confirmed_by == "human"' "$human_file" >/dev/null 2>&1; then
  pass "preflight: --persist without --yes records confirmed_by=human"
else
  fail "preflight: --persist without --yes records confirmed_by=human"
fi

# A missing dependency is not a preference — --yes must NOT waive it.
TRACK_ID=tst-prereq TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  PREFLIGHT_REQUIRE_TOOLCHAIN="definitely-not-a-real-bin" \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --yes >/dev/null 2>&1 \
  && fail "preflight: --yes still hard-fails an unmet prerequisite" \
  || pass "preflight: --yes still hard-fails an unmet prerequisite"
rm -f "$TMPDIR_RUNS"/*.dispatch

# --complete stamps completed_utc + numeric duration_secs (write-once) at PR handoff
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-done TASKS="T001" TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --commit >/dev/null 2>&1
TRACK_ID=tst-done TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --complete >/dev/null 2>&1
done_file=$(ls "$TMPDIR_RUNS"/*tst-done*.dispatch 2>/dev/null | head -1)
if [ -n "$done_file" ] && jq -e '(.completed_utc | type == "string" and . != "") and (.duration_secs | type == "number")' "$done_file" >/dev/null 2>&1; then
  pass "preflight: --complete stamps completed_utc + numeric duration_secs"
else
  fail "preflight: --complete stamps completed_utc + numeric duration_secs"
fi
# write-once: a second --complete must not overwrite the original finish time
first_done=$(jq -r '.completed_utc' "$done_file" 2>/dev/null)
TRACK_ID=tst-done TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --complete >/dev/null 2>&1
[ "$(jq -r '.completed_utc' "$done_file" 2>/dev/null)" = "$first_done" ] \
  && pass "preflight: --complete is write-once (resume can't clobber finish time)" \
  || fail "preflight: --complete is write-once (resume can't clobber finish time)"
rm -f "$TMPDIR_RUNS"/*.dispatch
TRACK_ID=tst-setup TASKS="T001-T005" TRACK_BASE_REF=main \
  PREFLIGHT_REQUIRE_GH=0 RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" --commit >/dev/null 2>&1

result=$(TRACK_ID=tst-setup TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>&1)
printf '%s' "$result" | grep -q '"mode":"resume"' \
  && pass "preflight: same slug -> RESUME mode" || fail "preflight: same slug -> RESUME mode"

result2=$(TRACK_ID=tst-other TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
          RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>&1)
printf '%s' "$result2" | grep -q '"mode":"start"' \
  && pass "preflight: different slug -> fresh START" \
  || fail "preflight: different slug -> fresh START"

RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null \
  && fail "preflight: missing TRACK_ID -> hard-fail exit 1" \
  || pass "preflight: missing TRACK_ID -> hard-fail exit 1"

result=$(TRACK_ID=tst-scope TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         TRACK_ALLOWED_PREFIXES="backend-go/:frontend/" RUNS_DIR="$TMPDIR_RUNS" \
         bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.scope_set == true and (.allowed_prefixes | index("backend-go/") != null)' >/dev/null 2>&1 \
  && pass "preflight: writable scope surfaced in JSON" \
  || fail "preflight: writable scope surfaced in JSON"

# TRACK_BRANCH: custom name wins; absent -> derived from the track slug; invalid -> hard-fail
result=$(TRACK_ID=tst-br TRACK_BRANCH="feat/custom-name" TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.branch == "feat/custom-name"' >/dev/null 2>&1 \
  && pass "preflight: TRACK_BRANCH override sets custom branch name" \
  || fail "preflight: TRACK_BRANCH override sets custom branch name"

result=$(TRACK_ID=tst-slug TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.branch == "tst-slug"' >/dev/null 2>&1 \
  && pass "preflight: no TRACK_BRANCH -> branch derived from track slug" \
  || fail "preflight: no TRACK_BRANCH -> branch derived from track slug"

TRACK_ID=tst-badbr TRACK_BRANCH="bad branch~name" TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
  RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" >/dev/null 2>&1 \
  && fail "preflight: invalid TRACK_BRANCH -> hard-fail exit 1" \
  || pass "preflight: invalid TRACK_BRANCH -> hard-fail exit 1"

result=$(TRACK_ID=tst-noscope TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.scope_set == false' >/dev/null 2>&1 \
  && pass "preflight: unset scope -> scope_set=false (guard fails closed)" \
  || fail "preflight: unset scope -> scope_set=false (guard fails closed)"

result=$(TRACK_ID=tst-tc TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         PREFLIGHT_REQUIRE_TOOLCHAIN="git,jq" TRACK_REQUIRED_EVIDENCE="go-test,py" \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.toolchain_set == true and (.require_toolchain | index("git") != null) and .evidence_floor_set == true and (.required_evidence | index("py") != null)' >/dev/null 2>&1 \
  && pass "preflight: toolchain + evidence floor surfaced in JSON" \
  || fail "preflight: toolchain + evidence floor surfaced in JSON"

result=$(TRACK_ID=tst-nofloor TRACK_BASE_REF=main PREFLIGHT_REQUIRE_GH=0 \
         RUNS_DIR="$TMPDIR_RUNS" bash "$PREFLIGHT" 2>/dev/null)
printf '%s' "$result" | jq -e '.evidence_floor_set == false and .toolchain_set == false' >/dev/null 2>&1 \
  && pass "preflight: unset floor/toolchain -> *_set=false (weaker gate flagged)" \
  || fail "preflight: unset floor/toolchain -> *_set=false (weaker gate flagged)"

# ---------------------------------------------------------------------------
# SUITE 2 -- track-reconcile.sh
# ---------------------------------------------------------------------------
section "track-reconcile.sh"

if [ -n "$RUN1_ID" ]; then
  printf '{"evidence":[{"kind":"go-test","cmd":"go test","response":"ok","fingerprint":"0000000000000000000000000000000000000001"}]}' \
    > "$TMPDIR_RUNS/$RUN1_ID.json"
  result=$(printf '{}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" TRACK_BASE_REF=main \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$RECONCILE" 2>/dev/null)
  printf '%s' "$result" | jq -e '.evidence.stale | index("go-test") != null' >/dev/null 2>&1 \
    && pass "reconcile: stale evidence identified" \
    || fail "reconcile: stale evidence identified"

  result=$(printf '{}' | TRACK_ID=tst-setup RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_BASE_REF=main bash "$RECONCILE" 2>/dev/null)
  printf '%s' "$result" | jq -e '.run_id != null' >/dev/null 2>&1 \
    && pass "reconcile: RUN_ID auto-recovered from breadcrumb" \
    || fail "reconcile: RUN_ID auto-recovered from breadcrumb"

  RECON_FP=$(printf '{}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
             TRACK_BASE_REF=main bash "$RECONCILE" 2>/dev/null | jq -r '.fingerprint')
  GATE_FP=$(current_fingerprint)
  [ "$RECON_FP" = "$GATE_FP" ] \
    && pass "reconcile: fingerprint == evidence-gate (bug-regression)" \
    || fail "reconcile: fingerprint mismatch (reconcile=$RECON_FP gate=$GATE_FP)"
else
  skip "reconcile: stale evidence (no RUN1_ID)"; skip "reconcile: auto-recovery (no RUN1_ID)"
  skip "reconcile: fingerprint parity (no RUN1_ID)"
fi

EMPTY_RUNS="$(mktemp -d)"
result=$(printf '{}' | RUNS_DIR="$EMPTY_RUNS" bash "$RECONCILE" 2>/dev/null)
[ -z "$result" ] && pass "reconcile: no breadcrumb -> silent no-op" \
  || fail "reconcile: no breadcrumb -> silent no-op"
rm -rf "$EMPTY_RUNS"

# --- position replay: the compaction re-anchor ---------------------------------
# Evidence freshness answers "which test kinds are current". It CANNOT answer "which
# core did I pick / are the tests frozen / where are my governance excerpts". These
# assertions cover the four resume_action branches that do.
POS_RUNS="$(mktemp -d)"; POS_RID="pos-run"
POS_GOV="$POS_RUNS/gov.md"; printf 'constraints\n' > "$POS_GOV"
printf '{"run_id":"%s","v":1,"trace":[],"evidence":[],"tool_calls":0}\n' "$POS_RID" > "$POS_RUNS/$POS_RID.json"

# (a) no phase recorded -> tell the caller to re-enter from the evidence verdict
result=$(printf '{}' | RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$RECONCILE" 2>/dev/null)
printf '%s' "$result" | jq -e '.position.phase == null and (.resume_action | test("No phase recorded"))' >/dev/null 2>&1 \
  && pass "reconcile: no phase -> resume_action says re-enter by evidence" \
  || fail "reconcile: no phase -> resume_action says re-enter by evidence"

# (b) phase + present bundle -> re-enter at that phase, re-read the bundle
RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$NOTE" phase refactor transform >/dev/null 2>&1 || true
RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$NOTE" governance "$POS_GOV" >/dev/null 2>&1 || true
result=$(printf '{}' | RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$RECONCILE" 2>/dev/null)
printf '%s' "$result" | jq -e '.position.phase.step == "transform"
        and .position.governance_bundle_present == true
        and (.resume_action | test("refactor/transform"))' >/dev/null 2>&1 \
  && pass "reconcile: replays phase + present governance bundle" \
  || fail "reconcile: replays phase + present governance bundle"

# (c) bundle recorded but GONE from disk -> must not point at a dead path
rm -f "$POS_GOV"
result=$(printf '{}' | RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$RECONCILE" 2>/dev/null)
printf '%s' "$result" | jq -e '.position.governance_bundle_present == false
        and (.resume_action | test("MISSING from disk"))' >/dev/null 2>&1 \
  && pass "reconcile: vanished governance bundle -> re-run discovery" \
  || fail "reconcile: vanished governance bundle -> re-run discovery"

# (d) terminal status -> never resume silently
RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$NOTE" status blocked "dep missing" >/dev/null 2>&1 || true
result=$(printf '{}' | RUN_ID="$POS_RID" RUNS_DIR="$POS_RUNS" bash "$RECONCILE" 2>/dev/null)
printf '%s' "$result" | jq -e '.position.status == "blocked"
        and (.resume_action | test("do NOT resume silently"))' >/dev/null 2>&1 \
  && pass "reconcile: terminal status -> refuses a silent resume" \
  || fail "reconcile: terminal status -> refuses a silent resume"
rm -rf "$POS_RUNS"

# ---------------------------------------------------------------------------
# SUITE 3 -- track-guard.sh (file edits)
# ---------------------------------------------------------------------------
section "track-guard.sh -- file ownership"

assert_allow "guard: path within allowed prefix -> allow" \
  "$GUARD" \
  "{\"tool_name\":\"create_file\",\"tool_input\":{\"filePath\":\"${ABS}backend-go/postgres.go\"}}" \
  "TRACK_ALLOWED_PREFIXES=backend-go/:frontend/"

assert_deny "guard: path outside allowed prefix -> deny" \
  "$GUARD" \
  "{\"tool_name\":\"create_file\",\"tool_input\":{\"filePath\":\"${ABS}backend-python/main.py\"}}" \
  "TRACK_ALLOWED_PREFIXES=backend-go/:frontend/"

assert_deny "guard: frozen entrypoint -> deny" \
  "$GUARD" \
  "{\"tool_name\":\"replace_string_in_file\",\"tool_input\":{\"filePath\":\"${ABS}backend-go/cmd/api/main.go\"}}" \
  "TRACK_ALLOWED_PREFIXES=backend-go/" \
  "TRACK_FROZEN_PATHS=backend-go/cmd/api/main.go"

TMP_GEN="$(mktemp "${REPO_ROOT}/sbd_tgen_XXXXXX.go")"
printf '// GENERATED \xe2\x80\x94 DO NOT EDIT\n// auto-generated\npackage main\n' > "$TMP_GEN"
result=$(printf '%s' \
  "{\"tool_name\":\"replace_string_in_file\",\"tool_input\":{\"filePath\":\"$TMP_GEN\"}}" \
  | TRACK_ALLOWED_PREFIXES=".github/sbd_tgen_" bash "$GUARD" 2>&1) || true
rm -f "$TMP_GEN"
# Must deny for the BANNER, not merely for being out of scope — so keep it in scope.
printf '%s' "$result" | grep -q 'GENERATED' \
  && pass "guard: GENERATED banner -> deny" || fail "guard: GENERATED banner -> deny (got: $result)"

REAL_COM=".github/instructions/go.instructions.md"
if git -C "$GIT_TOP" log --oneline -1 -- "$REAL_COM" 2>/dev/null | grep -q .; then
  assert_deny "guard: committed file under immutable prefix -> deny" \
    "$GUARD" \
    "{\"tool_name\":\"replace_string_in_file\",\"tool_input\":{\"filePath\":\"${ABS}${REAL_COM}\"}}" \
    "TRACK_ALLOWED_PREFIXES=.github/" \
    "TRACK_IMMUTABLE_PREFIXES=.github/instructions/"
else skip "guard: immutable prefix (file not committed)"; fi

assert_deny "guard: multi_replace with one out-of-scope path -> deny" \
  "$GUARD" \
  "{\"tool_name\":\"multi_replace_string_in_file\",\"tool_input\":{\"replacements\":[{\"filePath\":\"${ABS}backend-go/kernel/auth.go\"},{\"filePath\":\"${ABS}backend-python/main.py\"}]}}" \
  "TRACK_ALLOWED_PREFIXES=backend-go/"

assert_deny "guard: unset TRACK_ALLOWED_PREFIXES -> fail-closed deny" \
  "$GUARD" \
  "{\"tool_name\":\"create_file\",\"tool_input\":{\"filePath\":\"${ABS}anything/test.py\"}}"

# --- scope must not depend on the hook's CWD ---------------------------------------
# TRACK_ALLOWED_PREFIXES is worktree-relative. A `cd` into a subdirectory in an earlier
# Bash call used to make a later edit strip to "contracts/agent-graph.md" — no longer a
# match for a scope naming "specs/001-x/contracts/" — and every scoped write was denied,
# which pushes the run toward ungoverned heredoc writes. Same class as the sibling-worktree
# case: the hook's CWD is not the worktree root and must never stand in for it.
CWD_REPO="$(mktemp -d)"
(
  cd "$CWD_REPO"
  git init -q; git config user.email t@t.test; git config user.name t
  mkdir -p specs/001-x/contracts src; : > seed; git add -A; git commit -qm init
)
cwd_guard() { # cwd_guard <run-from-dir> <path-as-the-tool-sends-it>
  ( cd "$1" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$2" \
    | TRACK_ALLOWED_PREFIXES="specs/001-x/" bash "$GUARD" 2>&1 ) || true; }

[ -z "$(cwd_guard "$CWD_REPO/specs/001-x" 'contracts/agent-graph.md')" ] \
  && pass "guard: relative path from a subdir resolves to the worktree root -> allow" \
  || fail "guard: relative path from a subdir resolves to the worktree root -> allow (got: $(cwd_guard "$CWD_REPO/specs/001-x" 'contracts/agent-graph.md'))"

[ -z "$(cwd_guard "$CWD_REPO/specs/001-x/contracts" "$CWD_REPO/specs/001-x/contracts/deep/new.md")" ] \
  && pass "guard: absolute path from a subdir, parent dir not yet created -> allow" \
  || fail "guard: absolute path from a subdir, parent dir not yet created -> allow"

# The fix must not open the scope: out-of-scope stays denied from any CWD.
printf '%s' "$(cwd_guard "$CWD_REPO/specs/001-x" '../../src/app.go')" | grep -q '"deny"' \
  && pass "guard: out-of-scope path from a subdir -> still denied" \
  || fail "guard: out-of-scope path from a subdir -> still denied"
printf '%s' "$(cwd_guard "$CWD_REPO/src" 'app.go')" | grep -q '"deny"' \
  && pass "guard: in-CWD but out-of-scope -> denied (CWD is not the scope)" \
  || fail "guard: in-CWD but out-of-scope -> denied (CWD is not the scope)"
rm -rf "$CWD_REPO"

# --- --force / --no-verify are git flags, not universal ones -------------------------
# A raw substring match denied every unrelated tool that takes a --force flag, with a
# message about rewriting git history that made no sense for the command — a false
# positive with no in-bounds alternative, which gets worked around rather than obeyed.
force_cmd() { printf '{"tool_name":"Bash","tool_input":{"command":%s}}' "$(jq -Rn --arg c "$1" '$c')"; }
for c in 'specify integration install claude --force' \
         'npm ci --force' \
         'uv pip install --force-reinstall requests'; do
  assert_allow "guard: non-git '--force' allowed ($c)" "$GUARD" "$(force_cmd "$c")" \
    "TRACK_ALLOWED_PREFIXES=src/"
done
for c in 'git push --force' \
         'git push --force-with-lease origin main' \
         'git commit --no-verify -m x' \
         'specify integration install claude --force && git push --force'; do
  assert_deny "guard: git '--force/--no-verify' still denied ($c)" "$GUARD" "$(force_cmd "$c")" \
    "TRACK_ALLOWED_PREFIXES=src/"
done

# ---------------------------------------------------------------------------
# SUITE 4 -- track-guard.sh (terminal lockout)
# ---------------------------------------------------------------------------
section "track-guard.sh -- terminal lockout"

# Test commands are injected at build time; see note at top of script.
T_PUSH_CMD="git push origin branch"
T_FPUSH_CMD="git push --force origin branch"
T_PRMERGE_CMD="gh pr merge 42 --merge"
T_RESETHARD_CMD="git reset --hard HEAD~1"
T_FFPUSH_CMD="git push origin mybranch"
T_DROP_CMD='DROP TABLE users'
T_FLUSH_CMD="redis-cli FLUSHALL"
T_RMRF_CMD="rm -rf /home/user/data"

mk_term() { printf '{"tool_name":"run_in_terminal","tool_input":{"command":"%s"}}' "$1"; }

assert_deny "guard: worker push blocked -> deny" \
  "$GUARD" "$(mk_term "$T_PUSH_CMD")" "TRACK_ALLOWED_PREFIXES=backend-go/"

assert_deny "guard: force-flag push blocked even with FF_PUSH -> deny" \
  "$GUARD" "$(mk_term "$T_FPUSH_CMD")" \
  "TRACK_ALLOWED_PREFIXES=backend-go/" "TRACK_ALLOW_FF_PUSH=1"

assert_deny "guard: pr-merge command blocked -> deny" \
  "$GUARD" "$(mk_term "$T_PRMERGE_CMD")" "TRACK_ALLOWED_PREFIXES=backend-go/"

assert_deny "guard: reset-hard command blocked -> deny" \
  "$GUARD" "$(mk_term "$T_RESETHARD_CMD")" "TRACK_ALLOWED_PREFIXES=backend-go/"

assert_allow "guard: ff-push with TRACK_ALLOW_FF_PUSH=1 -> allow" \
  "$GUARD" "$(mk_term "$T_FFPUSH_CMD")" \
  "TRACK_ALLOWED_PREFIXES=backend-go/" "TRACK_ALLOW_FF_PUSH=1"

# --- first-publish carve-out -------------------------------------------------------
# `gh pr create` cannot open a PR for a branch the remote has never seen, and fails
# non-interactively rather than offering to push. Denying that push made the skill's own
# terminal step unreachable — on a real run the worker escaped by self-granting
# TRACK_ALLOW_FF_PUSH, a flag meant for something else. The carve-out must be exactly
# wide enough to publish ONE branch ONCE, so both directions are pinned here.
PUB="$(mktemp -d)"
( cd "$PUB" && git init -q --bare remote.git && git clone -q remote.git work \
  && cd work && git config user.email t@t && git config user.name t \
  && git commit -q --allow-empty -m init && git branch -M main \
  && git push -q origin main && git checkout -qb feat/mywork ) >/dev/null 2>&1
pub() { # pub <label> <cmd> <ALLOW|DENY>
  local out got
  out="$( cd "$PUB/work" && printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$2" \
          | TRACK_ALLOWED_PREFIXES="src/" TRACK_DEFAULT_BRANCH=main bash "$GUARD" 2>&1 )"
  got=DENY; printf '%s' "$out" | grep -q '"deny"' || got=ALLOW
  [ "$got" = "$3" ] && pass "guard: $1" || fail "guard: $1 (got $got, want $3)"
}
pub "publishing own unpublished branch -> allow"   "git push -u origin feat/mywork"      ALLOW
pub "publishing via HEAD -> allow"                 "git push -u origin HEAD"             ALLOW
pub "publish must not target the base branch"      "git push origin main"                DENY
pub "publish must not redirect (HEAD:main)"        "git push origin HEAD:main"           DENY
pub "publish must not push another branch"         "git push origin feat/other"          DENY
pub "publish must not delete a remote branch"      "git push origin --delete feat/mywork" DENY
pub "publish must not be a bulk push (--all)"      "git push --all origin"               DENY
pub "publish must not carry --force"               "git push --force origin feat/mywork" DENY
# Once the branch exists on the remote it is an UPDATE — the rework flag keeps its meaning.
( cd "$PUB/work" && git push -q -u origin feat/mywork ) >/dev/null 2>&1
pub "second push of a published branch -> deny"    "git push origin feat/mywork"         DENY
rm -rf "$PUB"

assert_deny "guard: DROP TABLE with TRACK_GUARD_DESTRUCTIVE -> deny" \
  "$GUARD" "$(mk_term "$T_DROP_CMD")" "TRACK_GUARD_DESTRUCTIVE=1"

assert_deny "guard: FLUSHALL with TRACK_GUARD_DESTRUCTIVE -> deny" \
  "$GUARD" "$(mk_term "$T_FLUSH_CMD")" "TRACK_GUARD_DESTRUCTIVE=1"

assert_deny "guard: rm-rf absolute path with TRACK_GUARD_DESTRUCTIVE -> deny" \
  "$GUARD" "$(mk_term "$T_RMRF_CMD")" "TRACK_GUARD_DESTRUCTIVE=1"

# Benign commands MUST pass — guards against an over-broad deny regex regression.
assert_allow "guard: benign 'go test' terminal command -> allow" \
  "$GUARD" "$(mk_term "go test ./...")" "TRACK_ALLOWED_PREFIXES=backend-go/"

assert_allow "guard: benign 'git status' terminal command -> allow" \
  "$GUARD" "$(mk_term "git status")" "TRACK_ALLOWED_PREFIXES=backend-go/"

# A tool that is neither a file-edit nor a terminal call falls through untouched.
assert_allow "guard: unrelated tool (read_file) -> allow (no interception)" \
  "$GUARD" '{"tool_name":"read_file","tool_input":{"filePath":"anything.go"}}'

# ---------------------------------------------------------------------------
# SUITE 5 -- track-evidence.sh (producer) + producer->gate contract
# ---------------------------------------------------------------------------
# The CAPTURE half of the evidence gate. Records here are PRODUCED by
# track-evidence.sh (never hand-written), then fed straight into the real gate so
# the producer->consumer contract (field shape + fingerprint parity) is exercised
# end-to-end. If the producer drifts from the gate, these fail — unit-only tests
# that hand-write the record would not.
section "track-evidence.sh (producer)"

PROD_RUNS="$(mktemp -d)"
PROD_RID="prod-$(date +%s)"

# no-op: RUN_ID unset -> nothing recorded
printf '{"tool_name":"run_in_terminal","tool_input":{"command":"go test ./..."}}' \
  | RUNS_DIR="$PROD_RUNS" TRACK_TEST_CMD_PATTERN="go test" bash "$EVIDENCE" >/dev/null 2>&1 || true
[ -z "$(ls -A "$PROD_RUNS" 2>/dev/null)" ] \
  && pass "evidence(producer): RUN_ID unset -> no record written" \
  || fail "evidence(producer): RUN_ID unset -> no record written"

# no-op: no matcher declared -> nothing recorded
printf '{"tool_name":"run_in_terminal","tool_input":{"command":"go test ./..."}}' \
  | RUN_ID="$PROD_RID" RUNS_DIR="$PROD_RUNS" bash "$EVIDENCE" >/dev/null 2>&1 || true
[ ! -f "$PROD_RUNS/$PROD_RID.json" ] \
  && pass "evidence(producer): no matcher set -> no record written" \
  || fail "evidence(producer): no matcher set -> no record written"

# no-op: non-terminal tool is ignored
printf '{"tool_name":"create_file","tool_input":{"filePath":"x.go"}}' \
  | RUN_ID="$PROD_RID" RUNS_DIR="$PROD_RUNS" TRACK_TEST_CMD_PATTERN="go test" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
[ ! -f "$PROD_RUNS/$PROD_RID.json" ] \
  && pass "evidence(producer): non-terminal tool -> no record" \
  || fail "evidence(producer): non-terminal tool -> no record"

# TRACK_TEST_CMD_PATTERN match -> recorded with default kind "test"
printf '{"tool_name":"run_in_terminal","tool_input":{"command":"go test ./..."},"tool_response":"ok  0.5s"}' \
  | RUN_ID="$PROD_RID" RUNS_DIR="$PROD_RUNS" TRACK_TEST_CMD_PATTERN="go test" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
kind_seen=$(jq -r '.evidence[-1].kind // empty' "$PROD_RUNS/$PROD_RID.json" 2>/dev/null)
[ "$kind_seen" = "test" ] \
  && pass "evidence(producer): TEST_CMD_PATTERN match -> kind=test recorded" \
  || fail "evidence(producer): TEST_CMD_PATTERN match -> kind=test (got: $kind_seen)"

# TRACK_EVIDENCE_KINDS label:pattern derivation (first match wins)
PROD_RID2="prod2-$(date +%s)"
printf '{"tool_name":"run_in_terminal","tool_input":{"command":"go test -race ./..."},"tool_response":"ok"}' \
  | RUN_ID="$PROD_RID2" RUNS_DIR="$PROD_RUNS" \
    TRACK_EVIDENCE_KINDS="go-test:go test -race;py:uv run pytest" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
kind2=$(jq -r '.evidence[-1].kind // empty' "$PROD_RUNS/$PROD_RID2.json" 2>/dev/null)
[ "$kind2" = "go-test" ] \
  && pass "evidence(producer): EVIDENCE_KINDS label derived (go-test)" \
  || fail "evidence(producer): EVIDENCE_KINDS label derived (got: $kind2)"

# --- forgery: a command that MENTIONS a test must not count as running one ---------
# Both cases below were observed manufacturing a complete required-evidence pack on a
# real run, because the pattern was matched against the raw command text.
PROD_FORGE="forge-$(date +%s)"
# 1. Writing the PR body. It embeds the evidence table, which quotes the very commands
#    being matched — so the report certified itself.
jq -nc '{tool_name:"Bash",
         tool_input:{command:"cat > pr-body.md <<'"'"'PRBODY_EOF'"'"'\n| go-test | `go test ./...` | pass |\ngo test ./... 2>&1\nPRBODY_EOF\nwc -l pr-body.md"},
         tool_response:{stdout:"220 pr-body.md"}}' \
  | RUN_ID="$PROD_FORGE" RUNS_DIR="$PROD_RUNS" TRACK_EVIDENCE_KINDS="go-test:go test" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
[ "$(jq -r '.evidence | length' "$PROD_RUNS/$PROD_FORGE.json" 2>/dev/null || echo 0)" = "0" ] \
  && pass "evidence(producer): heredoc body quoting a test command is NOT captured" \
  || fail "evidence(producer): heredoc body quoting a test command was captured as evidence"

# 2. Echoing a payload into a hook while debugging it.
jq -nc '{tool_name:"Bash",
         tool_input:{command:"echo '"'"'{\"command\":\"npx tsc --noEmit\"}'"'"' | bash track-evidence.sh"},
         tool_response:{stdout:"exit: 0"}}' \
  | RUN_ID="$PROD_FORGE" RUNS_DIR="$PROD_RUNS" TRACK_EVIDENCE_KINDS="ts:tsc --noEmit" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
[ "$(jq -r '.evidence | length' "$PROD_RUNS/$PROD_FORGE.json" 2>/dev/null || echo 0)" = "0" ] \
  && pass "evidence(producer): test command inside a quoted literal is NOT captured" \
  || fail "evidence(producer): quoted-literal test command was captured as evidence"

# ...while a real invocation still is, including with a prefix and quoted arguments.
jq -nc '{tool_name:"Bash",tool_input:{command:"npx tsc --noEmit --pretty \"false\""},
         tool_response:{stdout:""}}' \
  | RUN_ID="$PROD_FORGE" RUNS_DIR="$PROD_RUNS" TRACK_EVIDENCE_KINDS="ts:tsc --noEmit" \
    bash "$EVIDENCE" >/dev/null 2>&1 || true
[ "$(jq -r '.evidence[-1].kind // empty' "$PROD_RUNS/$PROD_FORGE.json" 2>/dev/null)" = "ts" ] \
  && pass "evidence(producer): real run with prefix + quoted args still captured" \
  || fail "evidence(producer): real run with prefix + quoted args was dropped"

# --- verdict is settled at capture, from the strongest signal available ------------
# Text-only grading passed captures that printed `exit: 1`, and the gate and the report
# each carried their OWN default pattern, so they could grade the same row differently.
PROD_V="verdict-$(date +%s)"
v_cap() { # v_cap <response-json> -> echo verdict
  jq -nc --argjson r "$1" '{tool_name:"Bash",tool_input:{command:"go test ./..."},tool_response:$r}' \
    | RUN_ID="$PROD_V" RUNS_DIR="$PROD_RUNS" TRACK_EVIDENCE_KINDS="go-test:go test" \
      bash "$EVIDENCE" >/dev/null 2>&1 || true
  jq -r '.evidence[-1].verdict // empty' "$PROD_RUNS/$PROD_V.json" 2>/dev/null
}
[ "$(v_cap '{"stdout":"no packages to test\nexit: 1"}')" = "fail" ] \
  && pass "evidence(producer): 'exit: 1' in output grades fail" \
  || fail "evidence(producer): 'exit: 1' in output was graded pass"
[ "$(v_cap '{"stdout":"ok example 0.4s","returnCodeInterpretation":"No matches found"}')" = "fail" ] \
  && pass "evidence(producer): returnCodeInterpretation (non-zero exit) grades fail" \
  || fail "evidence(producer): returnCodeInterpretation ignored"
[ "$(v_cap '{"stdout":"ok example 0.4s  PASS"}')" = "pass" ] \
  && pass "evidence(producer): a genuinely clean run grades pass" \
  || fail "evidence(producer): a clean run was graded fail"
[ "$(v_cap '{"stdout":"done","exit_code":3}')" = "fail" ] \
  && pass "evidence(producer): explicit exit_code beats clean-looking text" \
  || fail "evidence(producer): explicit exit_code ignored"

# --- the fingerprint must follow the WORKTREE, not the hook's CWD -------------------
# A PostToolUse hook inherits the session CWD — the main checkout — even while the agent
# edits a linked worktree. Fingerprinting there describes a tree nobody is touching: on a
# real run every capture shared one fingerprint across three days of file creation, so the
# gate's staleness check was inert and the audit's E1 "converged" passed for that reason.
FP_WT="$(mktemp -d)"
( cd "$FP_WT" && git init -q main && cd main && git config user.email t@t && git config user.name t \
  && git commit -q --allow-empty -m init && git worktree add -q ../tree -b feat/fp ) >/dev/null 2>&1
mkdir -p "$FP_WT/main/runs"
printf '{"run_id":"fpw","branch":"feat/fp"}\n' > "$FP_WT/main/runs/fpw.dispatch"
fp_cap() { ( cd "$FP_WT/main" \
    && printf '{"tool_name":"Bash","tool_input":{"command":"go test ./..."},"tool_response":{"stdout":"ok"}}' \
       | RUN_ID=fpw RUNS_DIR="$FP_WT/main/runs" TRACK_EVIDENCE_KINDS="go-test:go test" \
         bash "$EVIDENCE" >/dev/null 2>&1 ) || true
  jq -r '.evidence[-1].fingerprint // empty' "$FP_WT/main/runs/fpw.json" 2>/dev/null; }
fp_a="$(fp_cap)"
echo "work happens here" > "$FP_WT/tree/newfile.go"   # worktree only; main is untouched
fp_b="$(fp_cap)"
[ -n "$fp_a" ] && [ "$fp_a" != "$fp_b" ] \
  && pass "evidence(producer): fingerprint tracks the run branch's worktree, not the hook CWD" \
  || fail "evidence(producer): fingerprint blind to worktree edits (fp_a=$fp_a fp_b=$fp_b)"
rm -rf "$FP_WT"

# Producer fingerprint MUST equal the current tree fingerprint (== gate's compute)
fp_prod=$(jq -r '.evidence[-1].fingerprint // empty' "$PROD_RUNS/$PROD_RID2.json" 2>/dev/null)
fp_now=$(current_fingerprint)
[ -n "$fp_prod" ] && [ "$fp_prod" = "$fp_now" ] \
  && pass "evidence(producer): fingerprint == current tree (producer<->gate parity)" \
  || fail "evidence(producer): fingerprint mismatch (producer=$fp_prod now=$fp_now)"

# END-TO-END: a producer-captured pass at the current FP satisfies the real gate
result=$(printf '{"stop_hook_active":false}' | RUN_ID="$PROD_RID2" RUNS_DIR="$PROD_RUNS" \
         TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
[ -z "$result" ] \
  && pass "evidence(e2e): producer pass at current FP -> gate allows" \
  || fail "evidence(e2e): producer pass -> gate allows (got: $result)"

# END-TO-END: a second required kind with no producer entry -> gate blocks, names it
result=$(printf '{"stop_hook_active":false}' | RUN_ID="$PROD_RID2" RUNS_DIR="$PROD_RUNS" \
         TRACK_REQUIRED_EVIDENCE="go-test,py" bash "$EVIDENCE_GATE" 2>&1) || true
if printf '%s' "$result" | grep -qiE '"block"|MISSING' && printf '%s' "$result" | grep -q 'py'; then
  pass "evidence(e2e): multi-kind, one kind missing -> gate blocks (names py)"
else fail "evidence(e2e): multi-kind missing -> gate blocks (got: $result)"; fi

rm -rf "$PROD_RUNS"

# ---------------------------------------------------------------------------
# SUITE 6 -- track-evidence-gate.sh
# ---------------------------------------------------------------------------
section "track-evidence-gate.sh"

if [ -n "$RUN1_ID" ]; then
  EMPTY_REC="$(mktemp -d)"
  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$EMPTY_REC" \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
  rm -rf "$EMPTY_REC"
  printf '%s' "$result" | grep -q '"block"' \
    && pass "evidence-gate: missing run record -> block" \
    || fail "evidence-gate: missing run record -> block"

  result=$(printf '{"stop_hook_active":true}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
  [ -z "$result" ] && pass "evidence-gate: stop_hook_active -> no-op" \
    || fail "evidence-gate: stop_hook_active -> no-op"

  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           bash "$EVIDENCE_GATE" 2>&1) || true
  [ -z "$result" ] && pass "evidence-gate: no required evidence -> no-op" \
    || fail "evidence-gate: no required evidence -> no-op"

  FP=$(current_fingerprint)
  jq -nc --arg fp "$FP" \
    '{"evidence":[{"kind":"go-test","cmd":"go test","response":"ok","fingerprint":$fp}]}' \
    > "$TMPDIR_RUNS/$RUN1_ID.json"
  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
  [ -z "$result" ] && pass "evidence-gate: fresh evidence at current FP -> allow" \
    || fail "evidence-gate: fresh evidence at current FP -> allow (got: $result)"

  jq -nc '{"evidence":[{"kind":"go-test","cmd":"go test","response":"ok","fingerprint":"0000000000000000000000000000000000000001"}]}' \
    > "$TMPDIR_RUNS/$RUN1_ID.json"
  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
  printf '%s' "$result" | grep -qiE '"block"|STALE' \
    && pass "evidence-gate: stale FP -> block" || fail "evidence-gate: stale FP -> block"

  FP=$(current_fingerprint)
  jq -nc --arg fp "$FP" \
    '{"evidence":[{"kind":"go-test","cmd":"go test","response":"--- FAIL: TestX\nFAIL\texit code 1","fingerprint":$fp}]}' \
    > "$TMPDIR_RUNS/$RUN1_ID.json"
  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_REQUIRED_EVIDENCE="go-test" bash "$EVIDENCE_GATE" 2>&1) || true
  printf '%s' "$result" | grep -qiE '"block"|FAILING' \
    && pass "evidence-gate: FAIL marker -> block" || fail "evidence-gate: FAIL marker -> block"

  # Multi-kind: one kind fresh+passing, a second REQUIRED kind absent -> block naming it.
  FP=$(current_fingerprint)
  jq -nc --arg fp "$FP" \
    '{"evidence":[{"kind":"go-test","cmd":"go test","response":"ok","fingerprint":$fp}]}' \
    > "$TMPDIR_RUNS/$RUN1_ID.json"
  result=$(printf '{"stop_hook_active":false}' | RUN_ID="$RUN1_ID" RUNS_DIR="$TMPDIR_RUNS" \
           TRACK_REQUIRED_EVIDENCE="go-test,py" bash "$EVIDENCE_GATE" 2>&1) || true
  if printf '%s' "$result" | grep -qiE '"block"|MISSING' && printf '%s' "$result" | grep -q 'py'; then
    pass "evidence-gate: multi-kind, second kind missing -> block names it"
  else fail "evidence-gate: multi-kind missing -> block (got: $result)"; fi
else
  for i in 1 2 3 4 5 6 7; do skip "evidence-gate: skipped (no RUN1_ID)"; done
fi

# --- documentation-only escape (TRACK_EVIDENCE_SKIP_GLOBS) -------------------------
# The floor is "required on EVERY diff" by design, but a prose-only diff cannot change a
# go/py/ts result — so demanding those kinds for it is a requirement no honest action can
# satisfy, and the run's only ways out are dishonest ones. Needs its own throwaway repo:
# the assertions turn on exactly which paths the diff touches.
SG_REPO="$(mktemp -d)"
(
  cd "$SG_REPO"
  git init -q; git config user.email t@t.test; git config user.name t
  printf 'runs/\n' > .gitignore          # else the run record itself lands in the diff
  : > seed.txt; git add -A; git commit -qm init
  mkdir -p runs docs specs/contracts
  printf '{"run_id":"sg","v":1,"trace":[],"evidence":[],"tool_calls":1}\n' > runs/sg.json
)
sg_gate() { ( cd "$SG_REPO" && printf '{"stop_hook_active":false}' \
  | RUN_ID=sg RUNS_DIR="$SG_REPO/runs" TRACK_REQUIRED_EVIDENCE="go-test,py" TRACK_BASE_REF="" \
    TRACK_EVIDENCE_SKIP_GLOBS="${1:-}" bash "$EVIDENCE_GATE" 2>&1 ) || true; }

printf 'prose\n' > "$SG_REPO/docs/a.md"; printf 'prose\n' > "$SG_REPO/specs/contracts/b.md"

printf '%s' "$(sg_gate '')" | grep -q '"block"' \
  && pass "evidence-gate: skip-globs UNSET -> prose-only diff still blocks (floor unchanged)" \
  || fail "evidence-gate: skip-globs UNSET -> prose-only diff still blocks (floor unchanged)"

[ -z "$(sg_gate '*.md;docs/*;specs/*')" ] \
  && pass "evidence-gate: every path matches a skip glob -> no-op" \
  || fail "evidence-gate: every path matches a skip glob -> no-op (got: $(sg_gate '*.md;docs/*;specs/*'))"

# ALL-or-nothing: one code file must restore the FULL requirement set, or the escape
# becomes a way to smuggle code past the floor.
printf 'package main\n' > "$SG_REPO/main.go"
printf '%s' "$(sg_gate '*.md;docs/*;specs/*')" | grep -q '"block"' \
  && pass "evidence-gate: one code file among prose -> full floor restored" \
  || fail "evidence-gate: one code file among prose -> full floor restored"
rm -f "$SG_REPO/main.go"

# A committed prose diff (not just untracked files) takes the same path.
( cd "$SG_REPO" && git add -A && git commit -qm docs )
sg_committed() { ( cd "$SG_REPO" && printf '{"stop_hook_active":false}' \
  | RUN_ID=sg RUNS_DIR="$SG_REPO/runs" TRACK_REQUIRED_EVIDENCE="go-test,py" TRACK_BASE_REF=HEAD~1 \
    TRACK_EVIDENCE_SKIP_GLOBS='*.md;docs/*;specs/*' bash "$EVIDENCE_GATE" 2>&1 ) || true; }
[ -z "$(sg_committed)" ] \
  && pass "evidence-gate: committed prose-only diff vs base -> no-op" \
  || fail "evidence-gate: committed prose-only diff vs base -> no-op (got: $(sg_committed))"

# An empty diff is NOT prose — the floor still applies, so this cannot become a free pass.
sg_empty() { ( cd "$SG_REPO" && printf '{"stop_hook_active":false}' \
  | RUN_ID=sg RUNS_DIR="$SG_REPO/runs" TRACK_REQUIRED_EVIDENCE="go-test,py" TRACK_BASE_REF="" \
    TRACK_EVIDENCE_SKIP_GLOBS='*.md;docs/*;specs/*' bash "$EVIDENCE_GATE" 2>&1 ) || true; }
printf '%s' "$(sg_empty)" | grep -q '"block"' \
  && pass "evidence-gate: empty diff + skip globs -> floor still applies" \
  || fail "evidence-gate: empty diff + skip globs -> floor still applies"
rm -rf "$SG_REPO"

# ---------------------------------------------------------------------------
# SUITE 7 -- track-sentinel.sh
# ---------------------------------------------------------------------------
section "track-sentinel.sh"

result=$(printf '{"stop_hook_active":true}' | TRACK_SENTINEL=1 bash "$SENTINEL" 2>&1) || true
[ -z "$result" ] && pass "sentinel: stop_hook_active -> no-op" \
  || fail "sentinel: stop_hook_active -> no-op"

result=$(printf '{"stop_hook_active":false}' | bash "$SENTINEL" 2>&1) || true
[ -z "$result" ] && pass "sentinel: TRACK_SENTINEL unset -> no-op" \
  || fail "sentinel: TRACK_SENTINEL unset -> no-op"

TMP_SECRET="sbd_tst_secret_$$.py"
# Deliberately split so push-protection scanners never see a valid key pattern.
# The sentinel checks for 'sk_' + 'live_' as separate regex components.
printf 'API_KEY = "sk_''live_''TEST_SENTINEL_FIXTURE_NOT_A_SECRET"\n' > "$TMP_SECRET"
git add "$TMP_SECRET"
SCRATCH_FILES+=("$TMP_SECRET")
result=$(printf '{"stop_hook_active":false}' | TRACK_SENTINEL=1 bash "$SENTINEL" 2>&1) || true
git rm --cached "$TMP_SECRET" --quiet 2>/dev/null || true; rm -f "$TMP_SECRET"
printf '%s' "$result" | grep -q '"block"' \
  && pass "sentinel: staged secret -> block" || fail "sentinel: staged secret -> block"

TMP_DEBUG="sbd_tst_debug_$$.ts"
printf 'export function foo() {\n  console.log("debug:", x);\n}\n' > "$TMP_DEBUG"
git add "$TMP_DEBUG"
SCRATCH_FILES+=("$TMP_DEBUG")
result=$(printf '{"stop_hook_active":false}' | TRACK_SENTINEL=1 bash "$SENTINEL" 2>&1) || true
git rm --cached "$TMP_DEBUG" --quiet 2>/dev/null || true; rm -f "$TMP_DEBUG"
printf '%s' "$result" | grep -q '"block"' \
  && pass "sentinel: console.log leftover -> block" || fail "sentinel: console.log leftover -> block"

# ---------------------------------------------------------------------------
# SUITE 8 -- track-meter.sh
# ---------------------------------------------------------------------------
section "track-meter.sh"

result=$(jq -nc '{"tool_name":"create_file","tool_response":"ok"}' | \
         RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" TRACK_MAX_TOOL_CALLS=100 \
         bash "$METER" 2>&1) || true
printf '%s' "$result" | grep -qF '"continue":false' \
  && fail "meter: under ceiling -> allow" || pass "meter: under ceiling -> allow"

result=$(jq -nc '{"tool_name":"create_file","tool_response":"ok"}' | \
         RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" TRACK_MAX_TOOL_CALLS=0 \
         bash "$METER" 2>&1) || true
printf '%s' "$result" | grep -qF '"continue":false' \
  && pass "meter: ceiling=0 -> block" || fail "meter: ceiling=0 -> block"

result=$(jq -nc '{"tool_name":"create_file","tool_response":"ok"}' | \
         RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" bash "$METER" 2>&1) || true
printf '%s' "$result" | grep -qF '"continue":false' \
  && fail "meter: unset ceiling -> no-op" || pass "meter: unset ceiling -> no-op"

# Accumulation + terminal state: three calls against a ceiling of 2 — the count
# must persist across calls, trip on the call that pushes it past the ceiling, and
# stamp status=no-progress for the orchestrator summary.
ACC_RUNS="$(mktemp -d)"; ACC_RID="meter-acc"
out=""
for _ in 1 2 3; do
  out=$(jq -nc '{"tool_name":"create_file","tool_response":"ok"}' | \
        RUN_ID="$ACC_RID" RUNS_DIR="$ACC_RUNS" TRACK_MAX_TOOL_CALLS=2 bash "$METER" 2>&1) || true
done
printf '%s' "$out" | grep -qF '"continue":false' \
  && pass "meter: count accumulates across calls, trips past ceiling" \
  || fail "meter: count accumulates across calls, trips past ceiling (got: $out)"
status_seen=$(jq -r '.status // empty' "$ACC_RUNS/$ACC_RID.json" 2>/dev/null)
[ "$status_seen" = "no-progress" ] \
  && pass "meter: ceiling trip records status=no-progress" \
  || fail "meter: ceiling trip records status=no-progress (got: $status_seen)"
rm -rf "$ACC_RUNS"

# Heartbeat: every meter write stamps started_ts (once) + last_ts (every call) so the
# orchestrator can derive idle-staleness and run wall-clock.
HB_RUNS="$(mktemp -d)"; HB_RID="meter-hb"
jq -nc '{"tool_name":"create_file","tool_response":"ok"}' | \
  RUN_ID="$HB_RID" RUNS_DIR="$HB_RUNS" TRACK_MAX_TOOL_CALLS=100 bash "$METER" >/dev/null 2>&1 || true
if jq -e '(.started_ts | type == "string" and . != "") and (.last_ts | type == "string" and . != "")' \
     "$HB_RUNS/$HB_RID.json" >/dev/null 2>&1; then
  pass "meter: stamps started_ts + last_ts heartbeat"
else
  fail "meter: stamps started_ts + last_ts heartbeat"
fi
rm -rf "$HB_RUNS"

# ---------------------------------------------------------------------------
# SUITE 9 -- track-trace.sh
# ---------------------------------------------------------------------------
section "track-trace.sh"

jq -nc '{"run_id":"'"${RUN1_ID:-test}"'","v":1,"trace":[],"evidence":[],"tool_calls":0}' \
  > "$TMPDIR_RUNS/${RUN1_ID:-test}.json"
jq -nc '{"hook_event_name":"SubagentStart","agent_id":"a001","agent_type":"impl"}' | \
  RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" bash "$TRACE" >/dev/null 2>&1 || true
trace_len=$(jq '.trace | length' "$TMPDIR_RUNS/${RUN1_ID:-test}.json" 2>/dev/null || echo 0)
[ "$trace_len" -ge 1 ] && pass "trace: SubagentStart -> appended to run record" \
  || fail "trace: SubagentStart -> appended to run record"

# enriched: agent_description (SubagentStart-only "why") is captured as reason
jq -nc '{"hook_event_name":"SubagentStart","agent_id":"a002","agent_type":"Explore","agent_description":"map the auth flow"}' | \
  RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" bash "$TRACE" >/dev/null 2>&1 || true
if jq -e '[.trace[] | select(.reason == "map the auth flow")] | length == 1' \
     "$TMPDIR_RUNS/${RUN1_ID:-test}.json" >/dev/null 2>&1; then
  pass "trace: agent_description captured as reason"
else
  fail "trace: agent_description captured as reason"
fi

# camelCase surface: agentName + stop_reason are read too
jq -nc '{"hook_event_name":"SubagentStop","agentName":"Explore","stop_reason":"end_turn"}' | \
  RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" bash "$TRACE" >/dev/null 2>&1 || true
if jq -e '[.trace[] | select(.agent_type == "Explore" and .stop_reason == "end_turn")] | length == 1' \
     "$TMPDIR_RUNS/${RUN1_ID:-test}.json" >/dev/null 2>&1; then
  pass "trace: camelCase agentName + stop_reason captured"
else
  fail "trace: camelCase agentName + stop_reason captured"
fi

result=$(jq -nc '{"hook_event_name":"SubagentStart"}' | bash "$TRACE" 2>&1) || true
[ -z "$result" ] && pass "trace: no RUN_ID -> no-op" || fail "trace: no RUN_ID -> no-op"

# ---------------------------------------------------------------------------
# SUITE 9b -- track-note.sh (SELF-REPORTED skills[] + iterations)
# ---------------------------------------------------------------------------
section "track-note.sh"
NOTE_RUNS="$(mktemp -d)"; NOTE_RID="note-run"

# skill: appends an ordered, provenance-tagged entry to skills[]
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" skill test-driven-development red >/dev/null 2>&1 || true
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" skill requesting-code-review review >/dev/null 2>&1 || true
if jq -e '(.skills | length == 2) and (.skills[0].skill == "test-driven-development") and (.skills[0].step == "red") and (.skills[0].self_reported == true)' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: skill appends ordered self_reported skills[] entry"
else
  fail "note: skill appends ordered self_reported skills[] entry"
fi

# loop: increments iterations, sets the provenance flag, logs the phase
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" loop cycle-1 >/dev/null 2>&1 || true
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" loop cycle-2 >/dev/null 2>&1 || true
if jq -e '.iterations == 2 and .iterations_self_reported == true and (.iteration_log | length == 2)' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: loop increments iterations + tags provenance + logs phase"
else
  fail "note: loop increments iterations + tags provenance + logs phase"
fi

# note writes preserve the canonical skeleton (co-exist with hook fields)
if jq -e 'has("run_id") and .v == 1 and (.trace | type == "array") and (.evidence | type == "array") and (.tool_calls | type == "number")' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: preserves canonical skeleton (run_id/v/trace/evidence/tool_calls)"
else
  fail "note: preserves canonical skeleton (run_id/v/trace/evidence/tool_calls)"
fi

# opt-in: no RUN_ID -> silent no-op, writes nothing
before=$(ls "$NOTE_RUNS" | wc -l)
RUNS_DIR="$NOTE_RUNS" bash "$NOTE" skill should-not-write >/dev/null 2>&1 || true
after=$(ls "$NOTE_RUNS" | wc -l)
[ "$before" -eq "$after" ] \
  && pass "note: no RUN_ID -> silent no-op (writes nothing)" \
  || fail "note: no RUN_ID -> silent no-op (writes nothing)"

# bad subcommand -> non-zero, no write
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" bogus >/dev/null 2>&1 \
  && fail "note: unknown subcommand -> non-zero exit" \
  || pass "note: unknown subcommand -> non-zero exit"

# --- phase: the compaction/crash re-anchor -------------------------------------
# `phase` is the SCALAR "where am I now" (overwritten) and phase_log[] the history.
# Both matter: reconcile reads the scalar, an auditor reads the log.
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" phase story red-batch >/dev/null 2>&1 || true
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" phase story green >/dev/null 2>&1 || true
if jq -e '.phase.mode == "story" and .phase.step == "green" and .phase.self_reported == true
          and (.phase_log | length == 2) and (.phase_log[0].step == "red-batch")' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: phase overwrites the scalar and appends to phase_log[]"
else
  fail "note: phase overwrites the scalar and appends to phase_log[]"
fi

RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" phase story >/dev/null 2>&1 \
  && fail "note: phase without <step> -> non-zero exit" \
  || pass "note: phase without <step> -> non-zero exit"

# --- governance: pin the persisted bundle (must exist on disk) -----------------
GOV_FILE="$NOTE_RUNS/gov.md"; printf 'binding constraints\n' > "$GOV_FILE"
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" governance "$GOV_FILE" >/dev/null 2>&1 || true
if jq -e --arg p "$GOV_FILE" '.governance_bundle.path == $p
          and (.governance_bundle.sha | length == 40)
          and .governance_bundle.self_reported == true' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: governance pins bundle path + sha"
else
  fail "note: governance pins bundle path + sha"
fi

# A bundle that does not exist must FAIL LOUD — recording a dead path would let a
# resumed run believe it has governance it cannot read.
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" governance "$NOTE_RUNS/absent.md" >/dev/null 2>&1 \
  && fail "note: governance with missing file -> non-zero exit" \
  || pass "note: governance with missing file -> non-zero exit"

# --- status: terminal state (the only writer of `blocked`) ---------------------
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" status blocked "flaky pg" "pin image tag" >/dev/null 2>&1 || true
if jq -e '.status == "blocked" and .status_self_reported == true
          and .blocker == "flaky pg" and .next_step == "pin image tag"' \
     "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1; then
  pass "note: status writes terminal state + blocker + next_step"
else
  fail "note: status writes terminal state + blocker + next_step"
fi

# Free-text states are rejected: the four names are the orchestrator's routing keys,
# so an invented one ("almost-done") would silently fall through every route.
RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" status almost-done >/dev/null 2>&1 \
  && fail "note: status rejects a non-enumerated state" \
  || pass "note: status rejects a non-enumerated state"

for st in success blocked no-progress budget-exceeded; do
  RUN_ID="$NOTE_RID" RUNS_DIR="$NOTE_RUNS" bash "$NOTE" status "$st" >/dev/null 2>&1 \
    || { fail "note: status accepts '$st'"; break; }
done
jq -e '.status == "budget-exceeded"' "$NOTE_RUNS/$NOTE_RID.json" >/dev/null 2>&1 \
  && pass "note: status accepts all four terminal states" \
  || fail "note: status accepts all four terminal states"

rm -rf "$NOTE_RUNS"

# ---------------------------------------------------------------------------
# SUITE 9c -- track-tokens.sh (opt-in transcript token estimate)
# ---------------------------------------------------------------------------
section "track-audit.sh"
# The audit re-derives discipline invariants from artifacts. Its value depends entirely
# on catching real violations AND on not inventing PASSes, so both directions are tested.
AUD_RUNS="$(mktemp -d)"; AUD_GOV="$AUD_RUNS/gov.md"
printf '# bundle\n## code-review-generic.instructions.md\n' > "$AUD_GOV"
aud_seed() { # aud_seed <run-id> — a clean, fully-disciplined story run
  local rid="$1"
  local sha; sha="$( { if command -v shasum >/dev/null 2>&1; then shasum "$AUD_GOV"; else sha1sum "$AUD_GOV"; fi; } | cut -d' ' -f1)"
  jq -nc --arg r "$rid" --arg p "$AUD_GOV" --arg s "$sha" \
    '{run_id:$r, v:1, tool_calls:5,
      phase:{mode:"story", step:"converge", t:"2026-01-02T00:00:00Z", self_reported:true},
      phase_log:[{t:"2026-01-01T00:00:00Z",mode:"story",step:"governance"},
                 {t:"2026-01-01T01:00:00Z",mode:"story",step:"red-batch"},
                 {t:"2026-01-01T02:00:00Z",mode:"story",step:"red-review"},
                 {t:"2026-01-01T03:00:00Z",mode:"story",step:"green"},
                 {t:"2026-01-01T04:00:00Z",mode:"story",step:"converge"}],
      governance_bundle:{path:$p, sha:$s, t:"2026-01-01T00:00:00Z", self_reported:true},
      status:"success",
      trace:[{t:"2026-01-01T00:30:00Z",kind:"subagent",event:"start",agent_id:"a1",agent_type:"maker"},
             {t:"2026-01-01T00:40:00Z",kind:"subagent",event:"start",agent_id:"a2",agent_type:"reviewer"}],
      evidence:[{t:"2026-01-01T01:00:00Z",kind:"go-test",cmd:"go test",response:"--- FAIL: TestX\nFAIL\nexit status 1",fingerprint:"fp0"},
                {t:"2026-01-01T04:00:00Z",kind:"go-test",cmd:"go test",response:"ok example 0.4s PASS all 12 tests passed",fingerprint:"fp1"}]}' \
    > "$AUD_RUNS/$rid.json"
}
# The audit derives `changed` from the REAL working diff, so every check reading it is a
# function of whatever the contributor happens to have edited. G4 (trust boundary) greps
# those paths for auth|secret|token|… — so editing a file whose NAME contains one of those
# words (track-tokens.sh does) flips G4 to FAIL and takes down every assertion in this
# section that expects a clean run, with nothing about the change being wrong.
#
# Pin the pattern section-wide to a sentinel matching no real path, so these cases test the
# record-derived checks they are actually about. Exported rather than threaded through each
# helper because the section invokes the audit directly in several places, and one missed
# call site brings the flakiness back. G4's own behaviour is asserted below in an isolated
# repo that sets the pattern explicitly, which overrides this.
export TRACK_TRUST_BOUNDARY_PATTERN="__no_such_trust_boundary_path__"

# Pinning the trust-boundary pattern was only half the leak. `changed` also drives G2 and G5
# (bundle coverage / bundle substance), which resolve `.github/instructions/*` globs against the
# REAL working diff — so editing this repo's own SKILL.md (matched by the ai-agent-* globs) made
# the seeded fake bundle "incomplete" and turned G2 into a FAIL, taking down every clean-run
# assertion here for reasons having nothing to do with the change. Run these cases from an
# isolated repo with a neutral diff and no .github/instructions/ at all: the record-derived
# checks behave identically, and the diff-derived ones WARN (nothing to match) instead of
# reading the contributor's working tree. G2/G4/G5/G6's own positive+negative paths are asserted
# below in purpose-built repos where the diff IS the fixture.
# Name deliberately distinct from the AUD_ISO used (and `rm -rf`'d) by the I1/I2/I3 cases
# further down — sharing it would delete this fixture mid-section and blank every later verdict.
# On its own branch, since I1 fails a run sitting on the default branch.
AUD_DIFF_ISO="$(mktemp -d)"
( cd "$AUD_DIFF_ISO" && git init -q . && git config user.email t@t && git config user.name t \
  && echo seed > seed.txt && git add -A && git commit -qm seed && git branch -M main \
  && git checkout -qb work/aud && echo note > notes.txt ) >/dev/null 2>&1
aud_json() { ( cd "$AUD_DIFF_ISO" && RUN_ID="$1" RUNS_DIR="$AUD_RUNS" TRACK_BASE_REF="main" \
               bash "$AUDIT" --json 2>/dev/null ); }
aud_verdict() { aud_json "$1" | jq -r --arg c "$2" '.checks[] | select(.id==$c) | .verdict'; }

# A clean run must NOT produce failures — a gate that always fires gets disabled.
aud_seed clean
if [ "$(aud_json clean | jq -r '.summary.fail')" = "0" ]; then
  pass "audit: a disciplined run produces zero FAILs"
else
  fail "audit: a disciplined run produces zero FAILs (got $(aud_json clean | jq -c '.checks[]|select(.verdict=="FAIL")'))"
fi
[ "$(aud_verdict clean G1)" = "PASS" ] && pass "audit: G1 passes when bundle exists + sha matches" || fail "audit: G1 passes when bundle exists + sha matches"
[ "$(aud_verdict clean T1)" = "PASS" ] && pass "audit: T1 confirms RED-before-green from evidence[]" || fail "audit: T1 confirms RED-before-green from evidence[]"

# G3 provenance. The ordering it checks compares a MODEL-written stamp
# (governance_bundle.t) against hook-written trace[] — so lowering that stamp satisfies it,
# and a real run did exactly that and then cited G3 as confirmation. The verdict is
# unchanged (a gate that fires on every run gets disabled); what must not regress is that
# the message says which side supported it, so a reviewer can weigh it.
aud_seed g3claim
g3_msg() { aud_json "$1" | jq -r '.checks[] | select(.id=="G3") | .message'; }
case "$(g3_msg g3claim)" in
  *"model's own stamp"*) pass "audit: G3 names a self-reported stamp when nothing corroborates it" ;;
  *) fail "audit: G3 does not disclose that it rests on a model-written stamp (got: $(g3_msg g3claim))" ;;
esac
# A hook-observed read of the pinned bundle before the first dispatch IS corroboration.
jq '.governance_reads=[{t:"2026-01-01T00:20:00Z",tool:"Read",via:"gov.md"}]' \
  "$AUD_RUNS/g3claim.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g3claim.json"
case "$(g3_msg g3claim)" in
  *corroborated*) pass "audit: G3 reports hook corroboration when a bundle read precedes dispatch" ;;
  *) fail "audit: G3 ignores hook-observed corroboration (got: $(g3_msg g3claim))" ;;
esac
[ "$(aud_verdict g3claim G3)" = "PASS" ] \
  && pass "audit: G3 verdict stays PASS in both provenance cases" \
  || fail "audit: G3 verdict changed unexpectedly"

# G4 both directions. Previously exercised only incidentally via the clean run, whose
# diff is whatever the contributor edited — so G4 could flip on an unrelated change and
# was never asserted on purpose. Run in an isolated repo with a known changed path.
G4_ISO="$(mktemp -d)"; ( cd "$G4_ISO" && git init -q . \
  && git config user.email t@t && git config user.name t \
  && echo x > seed && git add -A && git commit -qm seed >/dev/null 2>&1 \
  && git branch -M main && mkdir -p src && echo y > src/auth-handler.go ) >/dev/null 2>&1
mkdir -p "$G4_ISO/runs"
g4_seed() { # g4_seed <bundle-body>
  printf '%s\n' "$1" > "$G4_ISO/bundle.md"
  jq -nc --arg p "$G4_ISO/bundle.md" \
    '{run_id:"g4",v:1,tool_calls:1,phase:{mode:"story",step:"green"},
      phase_log:[{t:"a",mode:"story",step:"governance"}],
      governance_bundle:{path:$p},trace:[],evidence:[]}' > "$G4_ISO/runs/g4.json"
}
_g4() { ( cd "$G4_ISO" && RUN_ID=g4 RUNS_DIR=runs TRACK_BASE_REF=main \
          TRACK_TRUST_BOUNDARY_PATTERN="auth|secret|token" \
          bash "$AUDIT" --json --warn-only 2>/dev/null ) \
        | jq -r '.checks[] | select(.id=="G4") | .verdict'; }
g4_seed '# bundle
## code-review-generic.instructions.md'
[ "$(_g4)" = "FAIL" ] \
  && pass "audit: G4 fails when a trust-boundary path is touched without security-and-owasp" \
  || fail "audit: G4 fails on trust-boundary path without security add-on (got $(_g4))"
g4_seed '# bundle
## security-and-owasp.instructions.md'
[ "$(_g4)" = "PASS" ] \
  && pass "audit: G4 passes once the bundle pulls in security-and-owasp" \
  || fail "audit: G4 passes once the bundle pulls in security-and-owasp (got $(_g4))"
rm -rf "$G4_ISO"

# G5 — bundle SUBSTANCE, both directions. G2 is a substring test: a bare heading satisfies it
# exactly as well as a distilled section does, so a bundle could pass coverage while carrying
# nothing any brief could embed. G5 reads the section body, so both shapes are pinned here.
G5_ISO="$(mktemp -d)"
( cd "$G5_ISO" && git init -q . && git config user.email t@t && git config user.name t \
  && echo seed > seed.txt && git add -A && git commit -qm seed && git branch -M main \
  && git checkout -qb work/g5 && mkdir -p .github/instructions \
  && printf -- '---\ndescription: go\napplyTo: '"'"'**/*.go'"'"'\n---\n# Go\n' \
       > .github/instructions/go.instructions.md \
  && printf 'package main\n' > app.go ) >/dev/null 2>&1
mkdir -p "$G5_ISO/runs"
g5_seed() { printf '%s\n' "$1" > "$G5_ISO/bundle.md"
  jq -nc --arg p "$G5_ISO/bundle.md" \
    '{run_id:"g5",v:1,tool_calls:1,phase:{mode:"story",step:"green"},
      phase_log:[{t:"2026-01-01T00:00:00Z",mode:"story",step:"governance"}],
      governance_bundle:{path:$p},trace:[],evidence:[]}' > "$G5_ISO/runs/g5.json"; }
_g5() { ( cd "$G5_ISO" && RUN_ID=g5 RUNS_DIR=runs TRACK_BASE_REF=main \
          TRACK_TRUST_BOUNDARY_PATTERN="__none__" bash "$AUDIT" --json --warn-only 2>/dev/null ) \
        | jq -r --arg c "$1" '.checks[] | select(.id==$c) | .verdict'; }
g5_seed '# bundle
## go.instructions.md — matched **/*.go'
[ "$(_g5 G2)" = "PASS" ] && [ "$(_g5 G5)" = "FAIL" ] \
  && pass "audit: G5 fails a heading with no constraints under it (which G2 still passes)" \
  || fail "audit: G5 fails a hollow section (got G2=$(_g5 G2) G5=$(_g5 G5))"
g5_seed '# bundle
## go.instructions.md — matched **/*.go
- see the file'
[ "$(_g5 G5)" = "FAIL" ] \
  && pass "audit: G5 fails a section whose only bullet is a pointer, not a constraint" \
  || fail "audit: G5 fails a pointer-only section (got $(_g5 G5))"
g5_seed '# bundle
## go.instructions.md — matched **/*.go
- errors wrapped with %w, never %v
- no naked returns in exported funcs'
[ "$(_g5 G5)" = "PASS" ] \
  && pass "audit: G5 passes once the section carries real distilled constraints" \
  || fail "audit: G5 passes on a substantive section (got $(_g5 G5))"
rm -rf "$G5_ISO"

# G6 — THE LAST HOP: did the brief carry the bundle, as observed at dispatch time? All five
# states, because this check replaced a manual item and a wrong verdict here either blocks a
# correct run or launders the exact failure the gate exists for.
g6_brief() { # g6_brief <matched> <total> <declared_na> <thin> <below_min>
  printf '{"t":"2026-01-01T05:00:00Z","tool":"Task","lines_total":%s,"lines_matched":%s,"min_lines":3,"declared_na":%s,"thin":%s,"below_min":%s}' \
    "$2" "$1" "$3" "$4" "$5"; }
g6_seed() { # g6_seed <run-id> <briefs-json>
  aud_seed "$1"
  jq --argjson b "$2" '.briefs = $b' "$AUD_RUNS/$1.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/$1.json"; }

g6_seed g6thin "[$(g6_brief 0 4 false true false)]"
[ "$(aud_verdict g6thin G6)" = "FAIL" ] \
  && pass "audit: G6 fails a brief that carried NONE of the bundle (the filename-passing mode)" \
  || fail "audit: G6 fails a zero-content brief (got $(aud_verdict g6thin G6))"
g6_seed g6ok "[$(g6_brief 4 4 false false false)]"
[ "$(aud_verdict g6ok G6)" = "PASS" ] \
  && pass "audit: G6 passes when every brief carried the bundle's constraints" \
  || fail "audit: G6 passes on governed briefs (got $(aud_verdict g6ok G6))"
g6_seed g6slice "[$(g6_brief 1 6 false false true)]"
[ "$(aud_verdict g6slice G6)" = "WARN" ] \
  && pass "audit: G6 warns (never fails) on a narrow cluster slice — a fan-out brief is a subset" \
  || fail "audit: G6 warns on a thin-but-nonzero slice (got $(aud_verdict g6slice G6))"
g6_seed g6na "[$(g6_brief 0 4 true false false)]"
[ "$(aud_verdict g6na G6)" = "PASS" ] \
  && pass "audit: G6 accepts an explicit 'GOVERNANCE: n/a' declaration for a research dispatch" \
  || fail "audit: G6 accepts a declared n/a dispatch (got $(aud_verdict g6na G6))"
# Honesty rule: no briefs recorded and the hook unwired must WARN, never PASS — otherwise an
# unobserved run reads exactly like a compliant one.
[ "$(aud_verdict clean G6)" = "WARN" ] \
  && pass "audit: G6 warns rather than passing when track-brief.sh is unwired" \
  || fail "audit: G6 warns when the brief hook is unwired (got $(aud_verdict clean G6))"

# G3 — a deliberate mid-core RE-PIN must stay legal. The old check compared the single
# overwritten governance_bundle.t against the first dispatch, so re-distilling after a later
# cluster widened the matched set moved that stamp past the dispatch and FAILED the run for
# doing the right thing. The stamp history is what makes the accurate question askable.
aud_seed g3repin
jq '.trace = [{"t":"2026-01-01T00:30:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a1"},
              {"t":"2026-01-01T03:00:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a2"}]
    | .governance_stamps = [{"t":"2026-01-01T00:00:00Z","path":"g","sha":"s1","self_reported":true},
                            {"t":"2026-01-01T02:00:00Z","path":"g","sha":"s2","self_reported":true}]
    | .governance_bundle.t = "2026-01-01T02:00:00Z"' \
  "$AUD_RUNS/g3repin.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g3repin.json"
[ "$(aud_verdict g3repin G3)" = "PASS" ] \
  && pass "audit: G3 allows a mid-core re-pin (dispatch between two stamps is governed)" \
  || fail "audit: G3 allows a mid-core re-pin (got $(aud_verdict g3repin G3))"
# …while a dispatch that precedes EVERY stamp is still ungoverned.
jq '.trace += [{"t":"2025-12-31T00:00:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a0"}]' \
  "$AUD_RUNS/g3repin.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g3repin.json"
[ "$(aud_verdict g3repin G3)" = "FAIL" ] \
  && pass "audit: G3 still fails a dispatch that precedes every governance pin" \
  || fail "audit: G3 fails a pre-pin dispatch (got $(aud_verdict g3repin G3))"
# G1 reports a re-pin as PASS, not as the "changed after pinning" WARN.
[ "$(aud_verdict g3repin G1)" = "PASS" ] \
  && pass "audit: G1 treats a re-pinned bundle as clean when it matches the latest pin" \
  || fail "audit: G1 accepts a re-pinned bundle (got $(aud_verdict g3repin G1))"

# Each violation must be caught.
aud_seed g1miss; jq '.governance_bundle.path="/nonexistent/gone.md"' "$AUD_RUNS/g1miss.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g1miss.json"
[ "$(aud_verdict g1miss G1)" = "FAIL" ] && pass "audit: G1 fails when the pinned bundle vanished from disk" || fail "audit: G1 fails when the pinned bundle vanished from disk"

aud_seed g1none; jq 'del(.governance_bundle)' "$AUD_RUNS/g1none.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g1none.json"
[ "$(aud_verdict g1none G1)" = "FAIL" ] && pass "audit: G1 fails when no bundle was ever pinned" || fail "audit: G1 fails when no bundle was ever pinned"

# G3 — governance must precede the first dispatch. This is the ordering fact that makes
# "the brief carried the constraints" even possible.
aud_seed g3bad; jq '.trace[0].t="2025-01-01T00:00:00Z"' "$AUD_RUNS/g3bad.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/g3bad.json"
[ "$(aud_verdict g3bad G3)" = "FAIL" ] && pass "audit: G3 fails when a subagent ran before governance was stamped" || fail "audit: G3 fails when a subagent ran before governance was stamped"
[ "$(aud_verdict clean G3)" = "PASS" ] && pass "audit: G3 passes when governance precedes the first dispatch" || fail "audit: G3 passes when governance precedes the first dispatch"

aud_seed p1none; jq 'del(.phase) | del(.phase_log)' "$AUD_RUNS/p1none.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/p1none.json"
[ "$(aud_verdict p1none P1)" = "FAIL" ] && pass "audit: P1 fails when no phase was ever stamped" || fail "audit: P1 fails when no phase was ever stamped"

aud_seed p2gap; jq '.phase_log=[{t:"2026-01-01T00:00:00Z",mode:"story",step:"governance"}]' "$AUD_RUNS/p2gap.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/p2gap.json"
[ "$(aud_verdict p2gap P2)" = "WARN" ] && pass "audit: P2 warns when the gate sequence has holes" || fail "audit: P2 warns when the gate sequence has holes"

aud_seed m1one; jq '.trace=[.trace[0]]' "$AUD_RUNS/m1one.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/m1one.json"
[ "$(aud_verdict m1one M1)" = "WARN" ] && pass "audit: M1 warns when one agent may have made and reviewed" || fail "audit: M1 warns when one agent may have made and reviewed"

# T1 — story mode with no failing capture means the tests never ran red.
aud_seed t1nored; jq '.evidence=[.evidence[1]]' "$AUD_RUNS/t1nored.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/t1nored.json"
[ "$(aud_verdict t1nored T1)" = "WARN" ] && pass "audit: T1 warns when story mode never recorded a RED" || fail "audit: T1 warns when story mode never recorded a RED"

# E1 — the convergence gate: lanes must share one fingerprint.
aud_seed e1split; jq '.evidence=[{t:"a",kind:"go",cmd:"c",response:"ok all tests passed cleanly here now",fingerprint:"fpA"},{t:"b",kind:"py",cmd:"c",response:"42 passed in 3.1s everything green",fingerprint:"fpB"}]' "$AUD_RUNS/e1split.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/e1split.json"
[ "$(aud_verdict e1split E1)" = "FAIL" ] && pass "audit: E1 fails when lanes never converged on one fingerprint" || fail "audit: E1 fails when lanes never converged on one fingerprint"

# E2 — a truncated PASS satisfies the evidence gate trivially; a short FAIL is normal.
aud_seed e2short; jq '.evidence=[{t:"a",kind:"go",cmd:"c",response:"ok",fingerprint:"fp1"}]' "$AUD_RUNS/e2short.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/e2short.json"
[ "$(aud_verdict e2short E2)" = "WARN" ] && pass "audit: E2 warns on a suspiciously short PASSING capture" || fail "audit: E2 warns on a suspiciously short PASSING capture"
aud_seed e2fail; jq '.evidence=[{t:"a",kind:"go",cmd:"c",response:"FAIL",fingerprint:"fp1"}]' "$AUD_RUNS/e2fail.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/e2fail.json"
[ "$(aud_verdict e2fail E2)" = "PASS" ] && pass "audit: E2 does NOT flag a short FAILING capture (it can't fake a pass)" || fail "audit: E2 does NOT flag a short FAILING capture"

aud_seed f1none; jq 'del(.status)' "$AUD_RUNS/f1none.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/f1none.json"
[ "$(aud_verdict f1none F1)" = "WARN" ] && pass "audit: F1 warns when no terminal state was recorded" || fail "audit: F1 warns when no terminal state was recorded"

# --- Isolation & resume (the early bracket) ------------------------------------
# Before these existed, a run that never isolated and never reconciled audited
# perfectly clean: every later gate can pass while the work was done on main.
AUD_ISO="$(mktemp -d)"; ( cd "$AUD_ISO" && git init -q . \
  && git config user.email t@t && git config user.name t \
  && echo x > a && git add -A && git commit -qm b >/dev/null 2>&1 \
  && git branch -M main ) >/dev/null 2>&1
mkdir -p "$AUD_ISO/runs"
jq -nc '{run_id:"iso",v:1,tool_calls:1,phase:{mode:"story",step:"green"},
         phase_log:[{t:"a",mode:"story",step:"governance"}],trace:[],evidence:[]}' \
  > "$AUD_ISO/runs/iso.json"
_iso() { ( cd "$AUD_ISO" && RUN_ID=iso RUNS_DIR=runs TRACK_BASE_REF=main \
           bash "$AUDIT" --json --warn-only 2>/dev/null ) \
         | jq -r --arg c "$1" '.checks[] | select(.id==$c) | .verdict'; }

[ "$(_iso I1)" = "FAIL" ] \
  && pass "audit: I1 fails when work was done on the default branch (never isolated)" \
  || fail "audit: I1 fails when work was done on the default branch (got $(_iso I1))"
[ "$(_iso I3)" = "WARN" ] \
  && pass "audit: I3 warns when no reconcile is on record" \
  || fail "audit: I3 warns when no reconcile is on record"

# A real feature branch clears I1's FAIL but still warns without a linked worktree,
# because branch-in-place is only the documented fallback.
( cd "$AUD_ISO" && git checkout -qb feat/x ) >/dev/null 2>&1
[ "$(_iso I1)" = "WARN" ] \
  && pass "audit: I1 warns on branch-in-place (no linked worktree)" \
  || fail "audit: I1 warns on branch-in-place (got $(_iso I1))"

# Breadcrumb drift: the approved branch and the actual branch must agree.
jq -nc '{run_id:"iso",branch:"some-other-branch",track:"iso"}' > "$AUD_ISO/runs/iso.dispatch"
[ "$(_iso I2)" = "WARN" ] \
  && pass "audit: I2 warns when work drifted off the branch approved at preflight" \
  || fail "audit: I2 warns when work drifted off the approved branch"
jq -nc '{run_id:"iso",branch:"feat/x",track:"iso"}' > "$AUD_ISO/runs/iso.dispatch"
[ "$(_iso I2)" = "PASS" ] \
  && pass "audit: I2 passes when work is on the approved branch" \
  || fail "audit: I2 passes when work is on the approved branch"

# track-reconcile.sh must leave the durable trace I3 reads — an invariant with no
# artifact cannot be audited, only hoped for.
# NOTE: reconcile reads the hook payload from stdin. Its [ -t 0 ] guard only skips that
# read on an interactive TTY — invoked from a script it will block on `cat` forever, so
# always feed it a payload (or </dev/null) from a test.
( cd "$AUD_ISO" && printf '{}' | RUN_ID=iso RUNS_DIR=runs TRACK_BASE_REF=main bash "$RECONCILE" ) >/dev/null 2>&1
jq -e '.last_reconcile.t | type == "string"' "$AUD_ISO/runs/iso.json" >/dev/null 2>&1 \
  && pass "reconcile: stamps last_reconcile into the run record" \
  || fail "reconcile: stamps last_reconcile into the run record"
[ "$(_iso I3)" = "PASS" ] \
  && pass "audit: I3 passes once reconcile has run" \
  || fail "audit: I3 passes once reconcile has run"
rm -rf "$AUD_ISO"

# Exit codes + the honesty contract.
RUN_ID=clean RUNS_DIR="$AUD_RUNS" bash "$AUDIT" >/dev/null 2>&1 \
  && pass "audit: clean run exits 0" || fail "audit: clean run exits 0"
RUN_ID=g1none RUNS_DIR="$AUD_RUNS" bash "$AUDIT" >/dev/null 2>&1 \
  && fail "audit: a FAIL exits 2 (blocks)" || pass "audit: a FAIL exits 2 (blocks)"
RUN_ID=g1none RUNS_DIR="$AUD_RUNS" bash "$AUDIT" --warn-only >/dev/null 2>&1 \
  && pass "audit: --warn-only reports without blocking" || fail "audit: --warn-only reports without blocking"
if aud_json clean | jq -e '(.manual | length) >= 5' >/dev/null 2>&1; then
  pass "audit: publishes its NOT-CHECKED list (never implies a clean bill of health)"
else
  fail "audit: publishes its NOT-CHECKED list"
fi

# I4 — the compaction gate. Once track-compact.sh made both halves durable, the checklist's
# highest-value MANUAL item became arithmetic; all four of its states are pinned here.
aud_compact() { # aud_compact <run-id> <compactions> <reads> <trace>
  aud_seed "$1"
  jq --argjson c "$2" --argjson r "$3" --argjson tr "$4" \
     '.compactions = $c | .governance_reads = $r | .trace = $tr' \
     "$AUD_RUNS/$1.json" > "$AUD_RUNS/$1.tmp" && mv "$AUD_RUNS/$1.tmp" "$AUD_RUNS/$1.json"
}
_disp='[{"t":"2026-01-01T11:00:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a1"}]'

# A dispatch after a compaction with no re-read in between — the silent failure itself.
aud_compact i4bad '[{"t":"2026-01-01T10:00:00Z"}]' '[]' "$_disp"
[ "$(aud_verdict i4bad I4)" = "FAIL" ] \
  && pass "audit: I4 fails a dispatch after a compaction with no bundle re-read" \
  || fail "audit: I4 fails a dispatch after a compaction with no bundle re-read"

# A re-read between the two clears it.
aud_compact i4good '[{"t":"2026-01-01T10:00:00Z"}]' '[{"t":"2026-01-01T10:30:00Z"}]' "$_disp"
[ "$(aud_verdict i4good I4)" = "PASS" ] \
  && pass "audit: I4 passes when the bundle was re-read before the next dispatch" \
  || fail "audit: I4 passes when the bundle was re-read before the next dispatch"

# A compaction with nothing dispatched after it briefed nothing — not a violation.
aud_compact i4nodisp '[{"t":"2026-01-01T12:00:00Z"}]' '[]' "$_disp"
[ "$(aud_verdict i4nodisp I4)" = "PASS" ] \
  && pass "audit: I4 does not fault a compaction with no dispatch after it" \
  || fail "audit: I4 does not fault a compaction with no dispatch after it"

# Absence of compactions must never read as proof. With the hook unwired a compaction would
# leave no trace at all, so the honest verdict is WARN — this is the honesty rule in code.
[ "$(aud_verdict clean I4)" = "WARN" ] \
  && pass "audit: I4 warns rather than passing when track-compact.sh is unwired" \
  || fail "audit: I4 warns rather than passing when track-compact.sh is unwired"

# I4's second half — the re-read is not the invariant; the brief carrying it is. A run that
# re-read the bundle and then briefed from memory anyway is the exact silent degradation this
# gate exists for, and track-brief.sh makes that join decidable.
aud_compact i4used '[{"t":"2026-01-01T10:00:00Z"}]' '[{"t":"2026-01-01T10:30:00Z"}]' "$_disp"
jq '.briefs = [{"t":"2026-01-01T10:45:00Z","tool":"Task","lines_total":4,"lines_matched":0,
                "min_lines":3,"declared_na":false,"thin":true,"below_min":false}]' \
  "$AUD_RUNS/i4used.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/i4used.json"
[ "$(aud_verdict i4used I4)" = "FAIL" ] \
  && pass "audit: I4 fails when the bundle was re-read but the next brief still carried none of it" \
  || fail "audit: I4 fails a re-read followed by an empty brief (got $(aud_verdict i4used I4))"
jq '.briefs[0] |= (.lines_matched = 4 | .thin = false)' \
  "$AUD_RUNS/i4used.json" > "$AUD_RUNS/t" && mv "$AUD_RUNS/t" "$AUD_RUNS/i4used.json"
[ "$(aud_verdict i4used I4)" = "PASS" ] \
  && pass "audit: I4 passes when the post-compaction brief carried the re-read bundle" \
  || fail "audit: I4 passes when the re-read was actually used (got $(aud_verdict i4used I4))"

# Regression: track-trace.sh stores the RAW hook event name ("SubagentStop"), never
# "start"/"stop". The old selector matched neither, so every check reading trace[] for a
# dispatch — G3 above all — silently reported "no subagent activity" on real runs.
aud_seed g3real
jq '.trace = [{"t":"2026-01-01T00:30:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a1"},
              {"t":"2026-01-01T00:40:00Z","kind":"subagent","event":"SubagentStop","agent_id":"a2"}]' \
  "$AUD_RUNS/g3real.json" > "$AUD_RUNS/g3real.tmp" && mv "$AUD_RUNS/g3real.tmp" "$AUD_RUNS/g3real.json"
_g3m="$(aud_json g3real | jq -r '.checks[]|select(.id=="G3")|.message')"
if [ "$(aud_verdict g3real G3)" = "PASS" ] && ! printf '%s' "$_g3m" | grep -q 'no subagent activity'; then
  pass "audit: G3 recognises real SubagentStop trace entries, not only 'start'/'stop'"
else
  fail "audit: G3 recognises real SubagentStop trace entries (got: $_g3m)"
fi

# Hook mode: opt-in, non-looping, and silent when clean.
# NOTE: capture output into a variable, never `script | grep -q`. This suite runs with
# `set -o pipefail`, and grep -q exits on its FIRST match — the still-writing script then
# takes SIGPIPE and the pipeline reports failure. For a `&& fail || pass` silence check
# that inverts the result into a false PASS, which is worse than no assertion at all.
_h() { printf '%s' "$1" | env "${@:2}" bash "$AUDIT" --hook 2>/dev/null || true; }

[ -z "$(_h '{}' RUN_ID=g1none RUNS_DIR="$AUD_RUNS")" ] \
  && pass "audit: --hook without TRACK_AUDIT is a silent no-op" \
  || fail "audit: --hook without TRACK_AUDIT is a silent no-op"

_hb="$(_h '{}' RUN_ID=g1none RUNS_DIR="$AUD_RUNS" TRACK_AUDIT=1)"
printf '%s' "$_hb" | jq -e '.decision == "block" and (.reason | test("G1"))' >/dev/null 2>&1 \
  && pass "audit: --hook blocks the Stop with the failing ids as the reason" \
  || fail "audit: --hook blocks the Stop with the failing ids as the reason"

# The block reason must carry the REMEDIATION, not just the finding — a blocked agent
# needs a next step, otherwise it retries the same thing.
printf '%s' "$_hb" | jq -e '.reason | test("fix:")' >/dev/null 2>&1 \
  && pass "audit: --hook block reason includes remediation" \
  || fail "audit: --hook block reason includes remediation"

[ -z "$(_h '{"stop_hook_active":true}' RUN_ID=g1none RUNS_DIR="$AUD_RUNS" TRACK_AUDIT=1)" ] \
  && pass "audit: --hook honors stop_hook_active (cannot loop)" \
  || fail "audit: --hook honors stop_hook_active (cannot loop)"

[ -z "$(_h '{}' RUN_ID=clean RUNS_DIR="$AUD_RUNS" TRACK_AUDIT=1)" ] \
  && pass "audit: --hook is silent on a clean run" \
  || fail "audit: --hook is silent on a clean run"

# No RUN_ID anywhere -> writes nothing, says nothing (bundle convention).
EMPTY_AUD="$(mktemp -d)"
RUNS_DIR="$EMPTY_AUD" bash "$AUDIT" >/dev/null 2>&1 \
  && pass "audit: no RUN_ID -> silent no-op" || fail "audit: no RUN_ID -> silent no-op"
rm -rf "$AUD_RUNS" "$EMPTY_AUD"

section "track-compact.sh"
# The recorder behind I4. It must capture a re-read in either form a model actually uses,
# ignore everything else, and never invent a read it did not observe.
CMP="$SCRIPTS_DIR/track-compact.sh"
CMP_RUNS="$(mktemp -d)"
cmp_fire() { printf '%s' "$1" | RUN_ID=c RUNS_DIR="$CMP_RUNS" bash "$CMP" >/dev/null 2>&1 || true; }
cmp_n() { jq -r "$1" "$CMP_RUNS/c.json" 2>/dev/null || echo ERR; }
printf '{"run_id":"c","v":1,"trace":[],"evidence":[],"tool_calls":0,"governance_bundle":{"path":"runs/c.governance.md","sha":"x"}}\n' > "$CMP_RUNS/c.json"

cmp_fire '{"hook_event_name":"PostCompact","trigger":"auto"}'
[ "$(cmp_n '.compactions|length')" = "1" ] \
  && pass "compact: PostCompact stamps compactions[]" || fail "compact: PostCompact stamps compactions[]"
[ "$(cmp_n '.compactions[0].trigger')" = "auto" ] \
  && pass "compact: the compaction trigger is preserved" || fail "compact: the compaction trigger is preserved"

cmp_fire '{"hook_event_name":"PostToolUse","tool_name":"Read","tool_input":{"file_path":"runs/c.governance.md"}}'
[ "$(cmp_n '.governance_reads|length')" = "1" ] \
  && pass "compact: a Read of the pinned bundle is recorded" || fail "compact: a Read of the pinned bundle is recorded"

# `cat runs/<id>.governance.md` is just as legitimate a re-read as the Read tool.
cmp_fire '{"hook_event_name":"PostToolUse","tool_name":"Bash","tool_input":{"command":"cat runs/c.governance.md"}}'
[ "$(cmp_n '.governance_reads|length')" = "2" ] \
  && pass "compact: a Bash re-read of the bundle counts too" || fail "compact: a Bash re-read of the bundle counts too"

cmp_fire '{"hook_event_name":"PostToolUse","tool_name":"Read","tool_input":{"file_path":"src/main.go"}}'
[ "$(cmp_n '.governance_reads|length')" = "2" ] \
  && pass "compact: an unrelated Read is ignored" || fail "compact: an unrelated Read is ignored"

cmp_fire '{"hook_event_name":"Notification"}'
[ "$(cmp_n '.compactions|length')" = "1" ] \
  && pass "compact: an unrelated event is a no-op" || fail "compact: an unrelated event is a no-op"

# No bundle pinned -> nothing a re-read could be recognised against; must not invent one.
printf '{"run_id":"d","v":1,"trace":[],"evidence":[],"tool_calls":0}\n' > "$CMP_RUNS/d.json"
printf '%s' '{"hook_event_name":"PostToolUse","tool_name":"Read","tool_input":{"file_path":"runs/d.governance.md"}}' \
  | RUN_ID=d RUNS_DIR="$CMP_RUNS" bash "$CMP" >/dev/null 2>&1 || true
[ "$(jq -r '.governance_reads // [] | length' "$CMP_RUNS/d.json")" = "0" ] \
  && pass "compact: no governance pin -> no read recorded" || fail "compact: no governance pin -> no read recorded"

# Bundle convention: no RUN_ID -> silent no-op, writes nothing.
printf '%s' '{"hook_event_name":"PostCompact"}' | RUNS_DIR="$CMP_RUNS" bash "$CMP" >/dev/null 2>&1 \
  && pass "compact: no RUN_ID -> silent no-op" || fail "compact: no RUN_ID -> silent no-op"
rm -rf "$CMP_RUNS"

# Wired on BOTH surfaces, or the recorder never runs and I4 can only ever WARN.
if grep -q 'track-compact' "$SCRIPT_DIR/../templates/claude-settings.json" 2>/dev/null \
   && grep -q 'track-compact' "$SCRIPT_DIR/../templates/track-hooks.json" 2>/dev/null; then
  pass "compact: wired in both the Claude Code and Copilot hook templates"
else
  fail "compact: wired in both the Claude Code and Copilot hook templates"
fi

# ---------------------------------------------------------------------------
# SUITE 9e -- track-brief.sh (did the brief carry the governance?)
# ---------------------------------------------------------------------------
section "track-brief.sh"
# The recorder behind G6. It reads the outgoing brief at PreToolUse — the only place the brief
# is observable — so its matcher decides whether the pipeline's last unobserved hop stays
# unobserved. Wrong in either direction is costly: a missed match FAILs a compliant run, a
# false match launders the filename-passing defect into a PASS.
BRF="$SCRIPTS_DIR/track-brief.sh"
[ -x "$BRF" ] || chmod +x "$BRF"
BRF_RUNS="$(mktemp -d)"; BRF_GOV="$BRF_RUNS/gov.md"
cat > "$BRF_GOV" <<'BRFGOV'
# Governance bundle — run b
Surface: **/*.go

## go.instructions.md — matched **/*.go
- errors wrapped with %w, never %v
- no naked returns in exported funcs

## security-and-owasp.instructions.md — matched
- pinned image digests, never :latest
- no default credentials committed; env placeholder + documented dev fallback
BRFGOV
brf_reset() {
  jq -nc --arg p "$BRF_GOV" '{run_id:"b",v:1,trace:[],evidence:[],tool_calls:0,
     governance_bundle:{path:$p,sha:"s1",t:"2026-01-01T00:00:00Z",self_reported:true}}' \
    > "$BRF_RUNS/b.json"; }
brf_fire() { # brf_fire <prompt> [env...]
  local p="$1"; shift || true
  jq -nc --arg pr "$p" '{hook_event_name:"PreToolUse",tool_name:"Task",tool_input:{prompt:$pr}}' \
    | env RUN_ID=b RUNS_DIR="$BRF_RUNS" "$@" bash "$BRF" >/dev/null 2>&1 || true; }
brf_last() { jq -r "$1" "$BRF_RUNS/b.json" 2>/dev/null || echo ERR; }

brf_reset
brf_fire '- errors wrapped with %w, never %v
- no naked returns in exported funcs
- pinned image digests, never :latest'
[ "$(brf_last '.briefs[-1].lines_matched')" = "3" ] && [ "$(brf_last '.briefs[-1].thin')" = "false" ] \
  && pass "brief: counts the bundle constraint lines a brief embedded" \
  || fail "brief: counts embedded constraints (got matched=$(brf_last '.briefs[-1].lines_matched'))"

# The defect the whole gate exists for: names the files, transfers nothing.
brf_reset
brf_fire 'Implement the go cluster. Follow go.instructions.md and security-and-owasp.instructions.md.'
[ "$(brf_last '.briefs[-1].thin')" = "true" ] && [ "$(brf_last '.briefs[-1].lines_matched')" = "0" ] \
  && pass "brief: a filename-only brief scores zero and is flagged thin" \
  || fail "brief: filename-only brief flagged thin (got $(brf_last '.briefs[-1]'))"
# …and it records WHICH sections were merely named, so the failure is legible, not just numeric.
[ "$(brf_last '[.briefs[-1].sections[]?] | length')" = "2" ] \
  && pass "brief: records the sections a brief named (recorded, never scored)" \
  || fail "brief: records named sections (got $(brf_last '.briefs[-1].sections'))"

# Re-wrapped, back-ticked, re-punctuated: still the same constraint. Matching must survive
# normal prose, or every honest brief trips the gate and the gate gets turned off.
brf_reset
brf_fire 'Constraints: (a) errors wrapped with `%w`, never `%v`; (b) pinned image digests, never `:latest`.'
[ "$(brf_last '.briefs[-1].lines_matched')" = "2" ] \
  && pass "brief: matching tolerates re-wording, back-ticks and punctuation" \
  || fail "brief: tolerant matching (got matched=$(brf_last '.briefs[-1].lines_matched'))"

# A fan-out brief carries only its cluster — below the threshold but NOT a violation.
brf_reset
brf_fire '- errors wrapped with %w, never %v'
[ "$(brf_last '.briefs[-1].thin')" = "false" ] && [ "$(brf_last '.briefs[-1].below_min')" = "true" ] \
  && pass "brief: a narrow cluster slice is below_min, not thin" \
  || fail "brief: cluster slice below_min (got $(brf_last '.briefs[-1]'))"

# The explicit opt-out — same rule as the bundle's ABSENT lines.
brf_reset
brf_fire 'GOVERNANCE: n/a — read-only research, returns findings only
Find where retries are implemented.'
[ "$(brf_last '.briefs[-1].declared_na')" = "true" ] && [ "$(brf_last '.briefs[-1].thin')" = "false" ] \
  && pass "brief: an explicit 'GOVERNANCE: n/a' declaration clears a research dispatch" \
  || fail "brief: declared n/a clears the dispatch (got $(brf_last '.briefs[-1]'))"

# Everything that is not a dispatch must be a no-op — this hook fires on every tool call on
# surfaces that cannot scope by matcher.
brf_reset
printf '%s' '{"hook_event_name":"PreToolUse","tool_name":"Read","tool_input":{"file_path":"main.go"}}' \
  | RUN_ID=b RUNS_DIR="$BRF_RUNS" bash "$BRF" >/dev/null 2>&1 || true
printf '%s' '{"hook_event_name":"PreToolUse","tool_name":"Task","tool_input":{"file_path":"x"}}' \
  | RUN_ID=b RUNS_DIR="$BRF_RUNS" bash "$BRF" >/dev/null 2>&1 || true
printf '%s' '{"hook_event_name":"PostToolUse","tool_name":"Task","tool_input":{"prompt":"anything"}}' \
  | RUN_ID=b RUNS_DIR="$BRF_RUNS" bash "$BRF" >/dev/null 2>&1 || true
[ "$(brf_last '.briefs // [] | length')" = "0" ] \
  && pass "brief: non-dispatch tool, promptless payload, and wrong event are all no-ops" \
  || fail "brief: ignores what it should (got $(brf_last '.briefs'))"

# Recording is the default; denial is opt-in. A false deny costs a dispatch, so the blocking
# form must be a choice — and when chosen it must deny only the zero-content case.
brf_reset
_bout="$(printf '%s' '{"hook_event_name":"PreToolUse","tool_name":"Task","tool_input":{"prompt":"just follow go.instructions.md"}}' \
  | RUN_ID=b RUNS_DIR="$BRF_RUNS" bash "$BRF" 2>/dev/null)"; _brc=$?
[ "$_brc" -eq 0 ] && pass "brief: records without blocking by default" \
  || fail "brief: default must not block (exit=$_brc)"
# Deny exits 2 by design, so the output has to be captured before it is inspected — piping
# straight into grep under `set -o pipefail` reports the hook's exit, not whether it denied.
brf_deny_out() { # brf_deny_out <prompt>
  jq -nc --arg pr "$1" '{hook_event_name:"PreToolUse",tool_name:"Task",tool_input:{prompt:$pr}}' \
    | { RUN_ID=b RUNS_DIR="$BRF_RUNS" TRACK_BRIEF_DENY=1 bash "$BRF" 2>/dev/null || true; }; }
brf_reset
case "$(brf_deny_out 'just follow go.instructions.md')" in
  *'"deny"'*) pass "brief: TRACK_BRIEF_DENY=1 denies a zero-content dispatch" ;;
  *) fail "brief: TRACK_BRIEF_DENY=1 denies a zero-content dispatch" ;;
esac
brf_reset
case "$(brf_deny_out '- errors wrapped with %w, never %v
- no naked returns in exported funcs
- pinned image digests, never :latest')" in
  *'"deny"'*) fail "brief: deny mode must still allow a governed brief" ;;
  *) pass "brief: deny mode still allows a governed brief" ;;
esac

# No bundle pinned -> nothing to carry; must not manufacture a violation (G1 owns that failure).
jq -nc '{run_id:"b",v:1,trace:[],evidence:[],tool_calls:0}' > "$BRF_RUNS/b.json"
brf_fire 'anything at all'
[ "$(brf_last '.briefs[-1].thin')" = "false" ] \
  && pass "brief: no bundle pinned -> the brief is recorded but never flagged thin" \
  || fail "brief: no bundle pinned must not flag thin (got $(brf_last '.briefs[-1]'))"

# Bundle convention: no RUN_ID -> silent no-op.
printf '%s' '{"hook_event_name":"PreToolUse","tool_name":"Task","tool_input":{"prompt":"x"}}' \
  | RUNS_DIR="$BRF_RUNS" bash "$BRF" >/dev/null 2>&1 \
  && pass "brief: no RUN_ID -> silent no-op" || fail "brief: no RUN_ID -> silent no-op"
rm -rf "$BRF_RUNS"

# Wired on BOTH surfaces, or G6 can only ever WARN. Claude Code scopes by matcher (Task);
# Copilot cannot, so the script's own tool-name branch is what keeps it cheap there.
if grep -q 'track-brief' "$SCRIPT_DIR/../templates/track-hooks.json" 2>/dev/null \
   && jq -e '[.hooks.PreToolUse[]? | select((.matcher // "") | test("Task"))
             | .hooks[]?.command] | map(test("track-brief")) | any' \
        "$SCRIPT_DIR/../templates/claude-settings.json" >/dev/null 2>&1; then
  pass "brief: wired on both surfaces (Copilot preToolUse + Claude PreToolUse/Task)"
else
  fail "brief: wired on both surfaces (Copilot preToolUse + Claude PreToolUse/Task)"
fi

section "track-tokens.sh"
TOK_RUNS="$(mktemp -d)"; TOK_RID="tok-run"
jq -nc '{"run_id":"'"$TOK_RID"'","v":1,"trace":[],"evidence":[],"tool_calls":0}' \
  > "$TOK_RUNS/$TOK_RID.json"

# Build a minimal transcript fixture with all three text-bearing record types.
TOK_TX="$(mktemp)"
printf '%s\n' \
  '{"type":"user.message","data":{"content":"implement the auth handler"}}' \
  '{"type":"assistant.message","data":{"content":"I will write the handler","reasoningText":"checking the spec","toolRequests":[{"name":"read_file","args":{"filePath":"auth.go"}}]}}' \
  '{"type":"tool.execution_start","data":{"toolName":"read_file","toolCallId":"t1","arguments":{"filePath":"auth.go"}}}' \
  '{"type":"tool.execution_complete","data":{"toolCallId":"t1","success":true}}' \
  > "$TOK_TX"

# With TRACK_MAX_TOKEN_ESTIMATE=200000 it should write token_estimate to the record.
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_TX" | \
  TRACK_MAX_TOKEN_ESTIMATE=200000 RUN_ID="$TOK_RID" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" >/dev/null 2>&1 || true
if jq -e '.token_estimate > 0 and (.token_estimate_method | test("chars")) and (.token_estimate_chars > 0)' \
     "$TOK_RUNS/$TOK_RID.json" >/dev/null 2>&1; then
  pass "tokens: writes token_estimate + method with TRACK_MAX_TOKEN_ESTIMATE=200000"
else
  fail "tokens: writes token_estimate + method with TRACK_MAX_TOKEN_ESTIMATE=200000"
fi

# Overwrite behaviour: a second Stop call must OVERWRITE, not add, the estimate.
est1="$(jq '.token_estimate' "$TOK_RUNS/$TOK_RID.json")"
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_TX" | \
  TRACK_MAX_TOKEN_ESTIMATE=200000 RUN_ID="$TOK_RID" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" >/dev/null 2>&1 || true
est2="$(jq '.token_estimate' "$TOK_RUNS/$TOK_RID.json")"
[ "$est1" -eq "$est2" ] \
  && pass "tokens: repeated Stop overwrites estimate (not additive)" \
  || fail "tokens: repeated Stop overwrites estimate (not additive)"

# Ceiling enforcement: a very low ceiling should block the first stop (exit 1) and
# set status=budget-exceeded, then allow the second stop (exit 0) once status is set.
TOK_CEIL_RID="tok-ceil"
jq -nc --arg rid "$TOK_CEIL_RID" '{"run_id":$rid,"v":1,"trace":[],"evidence":[],"tool_calls":5}' \
  > "$TOK_RUNS/$TOK_CEIL_RID.json"
budget_exit=0
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_TX" | \
  TRACK_MAX_TOKEN_ESTIMATE=1 RUN_ID="$TOK_CEIL_RID" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" 2>/dev/null \
  || budget_exit=$?
if [ "$budget_exit" -ne 0 ] && jq -e '.status == "budget-exceeded"' "$TOK_RUNS/$TOK_CEIL_RID.json" >/dev/null 2>&1; then
  pass "tokens: ceiling enforcement — first stop blocked + status=budget-exceeded written"
else
  fail "tokens: ceiling enforcement — first stop blocked + status=budget-exceeded written (exit=$budget_exit)"
fi
# Second stop with status already set must exit 0 (allow clean run end).
budget_exit2=0
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_TX" | \
  TRACK_MAX_TOKEN_ESTIMATE=1 RUN_ID="$TOK_CEIL_RID" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" 2>/dev/null \
  || budget_exit2=$?
[ "$budget_exit2" -eq 0 ] \
  && pass "tokens: ceiling enforcement — second stop allowed (status already budget-exceeded)" \
  || fail "tokens: ceiling enforcement — second stop allowed (budget_exit2=$budget_exit2)"

# No-op when TRACK_MAX_TOKEN_ESTIMATE=0 (the field must not appear).
jq -nc '{"run_id":"tok-off","v":1,"trace":[],"evidence":[],"tool_calls":0}' \
  > "$TOK_RUNS/tok-off.json"
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_TX" | \
  TRACK_MAX_TOKEN_ESTIMATE=0 RUN_ID="tok-off" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" >/dev/null 2>&1 || true
if jq -e '.token_estimate == null' "$TOK_RUNS/tok-off.json" >/dev/null 2>&1; then
  pass "tokens: no-op when TRACK_MAX_TOKEN_ESTIMATE=0"
else
  fail "tokens: no-op when TRACK_MAX_TOKEN_ESTIMATE=0"
fi

# --- transcript schema coverage ---------------------------------------------------
# The fixture above is the dotted-`.type` schema. Claude Code writes a BARE .type with
# the text under .message.content — reading only one schema silently yields 0 chars,
# which then disables the ceiling entirely (0 never exceeds it), so the budget guard
# fails open with no symptom beyond a `~0` in the PR body.
TOK_CC="$(mktemp)"
printf '%s\n' \
  '{"type":"user","message":{"content":"implement the handler for this task"}}' \
  '{"type":"assistant","message":{"content":[{"type":"text","text":"writing it now"}]}}' \
  > "$TOK_CC"
jq -nc '{"run_id":"tok-cc","v":1,"trace":[],"evidence":[],"tool_calls":0}' > "$TOK_RUNS/tok-cc.json"
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_CC" | \
  TRACK_MAX_TOKEN_ESTIMATE=200000 RUN_ID="tok-cc" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" >/dev/null 2>&1 || true
jq -e '.token_estimate > 0' "$TOK_RUNS/tok-cc.json" >/dev/null 2>&1 \
  && pass "tokens: bare .type/.message.content transcript schema is counted" \
  || fail "tokens: bare .type/.message.content transcript schema counted as 0 (ceiling fails open)"

# --- provider usage beats the heuristic --------------------------------------------
# When the transcript carries the API's own per-turn usage, use it: it is authoritative
# and already includes the system prompt and tool schemas the heuristic is blind to.
TOK_USE="$(mktemp)"
printf '%s\n' \
  '{"type":"assistant","message":{"content":[{"type":"text","text":"hi"}],"usage":{"input_tokens":10,"output_tokens":100,"cache_read_input_tokens":9000,"cache_creation_input_tokens":400}}}' \
  '{"type":"assistant","message":{"content":[{"type":"text","text":"ho"}],"usage":{"input_tokens":5,"output_tokens":50,"cache_read_input_tokens":9000,"cache_creation_input_tokens":100}}}' \
  > "$TOK_USE"
jq -nc '{"run_id":"tok-use","v":1,"trace":[],"evidence":[],"tool_calls":0}' > "$TOK_RUNS/tok-use.json"
printf '{"hook_event_name":"Stop","transcript_path":"%s"}' "$TOK_USE" | \
  TRACK_MAX_TOKEN_ESTIMATE=200000 RUN_ID="tok-use" RUNS_DIR="$TOK_RUNS" bash "$TOKENS" >/dev/null 2>&1 || true
# estimate = input(15) + cache_write(500) + output(150) = 665; cache_read is excluded.
if jq -e '.token_estimate == 665
          and (.token_estimate_method | test("authoritative"))
          and .token_usage.cache_read == 18000' "$TOK_RUNS/tok-use.json" >/dev/null 2>&1; then
  pass "tokens: message.usage preferred; estimate excludes cache_read, breakdown recorded"
else
  fail "tokens: message.usage handling (got $(jq -c '{token_estimate,token_usage}' "$TOK_RUNS/tok-use.json" 2>/dev/null))"
fi

rm -rf "$TOK_RUNS" "$TOK_TX" "$TOK_CC" "$TOK_USE"

# ---------------------------------------------------------------------------
# SUITE 10 -- track-notify.sh
# ---------------------------------------------------------------------------
# Best-effort, fire-and-forget: with no webhook configured it must stay a silent
# no-op and NEVER emit a blocking decision (it runs on Stop after the gate).
section "track-notify.sh"

result=$(printf '{}' | RUN_ID="${RUN1_ID:-test}" RUNS_DIR="$TMPDIR_RUNS" bash "$NOTIFY" 2>&1) || true
[ -z "$result" ] \
  && pass "notify: no webhook -> silent no-op (never blocks)" \
  || fail "notify: no webhook -> silent no-op (got: $result)"

# ---------------------------------------------------------------------------
# SUITE 10b -- install-hooks.sh (idempotent, consent-gated, drift-aware, stack-aware)
# ---------------------------------------------------------------------------
section "install-hooks.sh"

# Build an isolated throwaway repo with go + python + spec signals; run the installer there.
IH_REPO="$(mktemp -d)"
(
  cd "$IH_REPO"
  git init -q
  mkdir -p backend-go backend-python specs/x migrations
  : > backend-go/go.mod; : > backend-python/pyproject.toml; : > specs/x/plan.md
)

# --check on a bare repo -> drift (exit 3), writes nothing
if ( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --check >/dev/null 2>&1 ); then
  fail "install: --check on unwired repo -> non-zero (drift)"
else
  pass "install: --check on unwired repo -> non-zero (drift)"
fi

# dry-run writes nothing
before_ct=$(find "$IH_REPO/.github/hooks" -type f 2>/dev/null | wc -l | tr -d ' ' || echo 0)
( cd "$IH_REPO" && bash "$INSTALL_HOOKS" >/dev/null 2>&1 ) || true
after_ct=$(find "$IH_REPO/.github/hooks" -type f 2>/dev/null | wc -l | tr -d ' ' || echo 0)
[ "$before_ct" = "$after_ct" ] \
  && pass "install: dry-run writes nothing" \
  || fail "install: dry-run writes nothing (before=$before_ct after=$after_ct)"

# --apply: syncs bundle, gitignores runs/, seeds base preset
( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --apply >/dev/null 2>&1 ) || true
if [ -f "$IH_REPO/.github/hooks/track-preflight.sh" ] && [ -f "$IH_REPO/.github/hooks/track-hooks.json" ]; then
  pass "install: --apply syncs bundle into .github/hooks/"
else
  fail "install: --apply syncs bundle into .github/hooks/"
fi
( cd "$IH_REPO" && git check-ignore runs/ >/dev/null 2>&1 ) \
  && pass "install: --apply gitignores runs/" \
  || fail "install: --apply gitignores runs/"
[ -f "$IH_REPO/.github/hooks/track-env.base.sh" ] \
  && pass "install: --apply seeds track-env.base.sh" \
  || fail "install: --apply seeds track-env.base.sh"

# stack-aware: detected go + py signals populate the evidence catalog + toolchain hint
if grep -q 'go-test:go test' "$IH_REPO/.github/hooks/track-env.base.sh" 2>/dev/null \
   && grep -q 'py:uv run pytest' "$IH_REPO/.github/hooks/track-env.base.sh" 2>/dev/null; then
  pass "install: base preset is stack-aware (go-test + py catalog from detected signals)"
else
  fail "install: base preset is stack-aware (go-test + py catalog from detected signals)"
fi

# TASK-DERIVED scope stays EMPTY so an unedited copy fails loud (guard denies all edits)
if grep -qE 'TRACK_ALLOWED_PREFIXES="\$\{TRACK_ALLOWED_PREFIXES:-\}"' "$IH_REPO/.github/hooks/track-env.base.sh" 2>/dev/null; then
  pass "install: TASK-DERIVED writable scope left empty (fail-loud)"
else
  fail "install: TASK-DERIVED writable scope left empty (fail-loud)"
fi

# generated base preset sources cleanly under the hooks' shell flags
if ( cd "$IH_REPO" && bash -c 'set -eufo pipefail; source .github/hooks/track-env.base.sh' >/dev/null 2>&1 ); then
  pass "install: generated track-env.base.sh sources cleanly (set -eufo pipefail)"
else
  fail "install: generated track-env.base.sh sources cleanly (set -eufo pipefail)"
fi

# after --apply, --check is clean (exit 0)
if ( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --check >/dev/null 2>&1 ); then
  pass "install: --check after --apply -> clean (exit 0)"
else
  fail "install: --check after --apply -> clean (exit 0)"
fi

# idempotent + never-clobber: edit the base preset, re-apply, edit must survive
printf '\n# USER EDIT MARKER\n' >> "$IH_REPO/.github/hooks/track-env.base.sh"
( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --apply >/dev/null 2>&1 ) || true
if grep -q 'USER EDIT MARKER' "$IH_REPO/.github/hooks/track-env.base.sh" 2>/dev/null; then
  pass "install: re-apply never clobbers an existing track-env.base.sh"
else
  fail "install: re-apply never clobbers an existing track-env.base.sh"
fi

# drift is repaired: stale an installed script, --check must flag it, --apply must fix it
printf '# STALE\n' > "$IH_REPO/.github/hooks/track-preflight.sh"
if ( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --check >/dev/null 2>&1 ); then
  fail "install: --check detects a drifted (stale) installed script"
else
  pass "install: --check detects a drifted (stale) installed script"
fi
( cd "$IH_REPO" && bash "$INSTALL_HOOKS" --apply >/dev/null 2>&1 ) || true
if cmp -s "$SCRIPTS_DIR/track-preflight.sh" "$IH_REPO/.github/hooks/track-preflight.sh"; then
  pass "install: --apply re-syncs a drifted script back to source"
else
  fail "install: --apply re-syncs a drifted script back to source"
fi
rm -rf "$IH_REPO"

# ---------------------------------------------------------------------------
# SUITE 10a2 -- the managed RUN_ID block must SELF-RETIRE
#
# Regression bracket for a bricked checkout observed in the field. `--complete` is
# reached at draft-PR handoff ONLY, so a run that ends any other way (ceiling trip,
# blocked, crash, abandon) used to leave an unconditional `export RUN_ID=...` behind
# forever. Every LATER session in that checkout then inherited a dead run: the meter
# re-read a record whose tool_calls already exceeded the ceiling and halted every tool
# call, and the evidence gate demanded the finished task's kinds. Adoption is now bound
# to "live AND on this run's branch", which retires the id on every exit path.
# ---------------------------------------------------------------------------
section "managed RUN_ID block -- self-retirement"

MB_REPO="$(mktemp -d)"
(
  cd "$MB_REPO"
  git init -q; git config user.email t@t.test; git config user.name t
  printf 'runs/\n' > .gitignore
  : > seed.txt; git add -A; git commit -qm init
  git checkout -q -b feat/mb
  mkdir -p .github/hooks
  cp "$SCRIPTS_DIR"/track-*.sh .github/hooks/
  printf 'export RUNS_DIR="${RUNS_DIR:-runs}"\n' > .github/hooks/track-env.base.sh
)
MB_ENV="$MB_REPO/.github/hooks/track-env.sh"
# Mint the run + write the managed block (feat/mb is the run's branch).
MB_ID="$( cd "$MB_REPO" && PREFLIGHT_REQUIRE_GH=0 TRACK_ID=mb TRACK_BRANCH=feat/mb \
          bash .github/hooks/track-preflight.sh --persist --yes 2>/dev/null )"
# What RUN_ID does a hook see after sourcing the env, exactly as the bootstrap does?
mb_runid() { ( cd "$MB_REPO" && bash -c 'set -eufo pipefail
  . .github/hooks/track-env.sh; . .github/hooks/track-env.base.sh; printf "%s" "${RUN_ID:-}"' ); }
mb_set_status() {  # write a terminal status into the run record
  printf '{"run_id":"%s","v":1,"trace":[],"evidence":[],"tool_calls":%s,"status":"%s"}\n' \
    "$MB_ID" "${2:-5}" "$1" > "$MB_REPO/runs/$MB_ID.json"; }
mb_clear_status() {
  printf '{"run_id":"%s","v":1,"trace":[],"evidence":[],"tool_calls":%s}\n' \
    "$MB_ID" "${1:-5}" > "$MB_REPO/runs/$MB_ID.json"; }

[ -n "$MB_ID" ] && grep -q 'track-preflight RUN_ID (managed' "$MB_ENV" 2>/dev/null \
  && pass "runid-block: --persist writes the managed block" \
  || fail "runid-block: --persist writes the managed block"

# The block is SOURCED by every hook on every tool call — a syntax error there breaks
# the whole bundle at once, so it must survive the hooks' own shell flags.
( cd "$MB_REPO" && bash -c 'set -eufo pipefail; . .github/hooks/track-env.sh' >/dev/null 2>&1 ) \
  && pass "runid-block: sources cleanly under set -eufo pipefail" \
  || fail "runid-block: sources cleanly under set -eufo pipefail"

mb_clear_status
[ "$(mb_runid)" = "$MB_ID" ] \
  && pass "runid-block: live run on its own branch -> adopted" \
  || fail "runid-block: live run on its own branch -> adopted (got '$(mb_runid)')"

# THE REPORTED BUG: a ceiling trip stamps no-progress and never reaches --complete.
mb_set_status no-progress 250
[ -z "$(mb_runid)" ] \
  && pass "runid-block: halted run (status no-progress) -> NOT re-adopted" \
  || fail "runid-block: halted run (status no-progress) -> NOT re-adopted"
for st in blocked budget-exceeded success; do
  mb_set_status "$st"
  [ -z "$(mb_runid)" ] \
    && pass "runid-block: terminal status '$st' -> NOT re-adopted" \
    || fail "runid-block: terminal status '$st' -> NOT re-adopted"
done

# Off-branch: a live run must not govern a session working on something else.
mb_clear_status
( cd "$MB_REPO" && git checkout -q -b docs/unrelated )
[ -z "$(mb_runid)" ] \
  && pass "runid-block: live run, different branch -> NOT adopted" \
  || fail "runid-block: live run, different branch -> NOT adopted"
( cd "$MB_REPO" && git checkout -q feat/mb )
[ "$(mb_runid)" = "$MB_ID" ] \
  && pass "runid-block: back on the run's branch -> adopted again" \
  || fail "runid-block: back on the run's branch -> adopted again"

# A caller's id (orchestrator per-worker value) outranks the file, always.
mb_set_status no-progress
[ "$( cd "$MB_REPO" && RUN_ID=caller-supplied bash -c 'set -eufo pipefail
      . .github/hooks/track-env.sh; printf "%s" "${RUN_ID:-}"' )" = "caller-supplied" ] \
  && pass "runid-block: an exported RUN_ID still wins over the block" \
  || fail "runid-block: an exported RUN_ID still wins over the block"

# End-to-end: the bricked checkout. Ceiling exhausted, run halted, block left behind —
# a later session on another branch must still be able to make a tool call.
mb_set_status no-progress 200
( cd "$MB_REPO" && git checkout -q docs/unrelated )
mb_halt="$( cd "$MB_REPO" && printf '{"tool_name":"Bash","tool_input":{"command":"ls"}}' \
            | TRACK_MAX_TOOL_CALLS=200 bash .github/hooks/track-meter.sh 2>&1 || true )"
printf '%s' "$mb_halt" | grep -q '"continue":false' \
  && fail "runid-block: stale halted run must not brick a later session's tool calls" \
  || pass "runid-block: stale halted run must not brick a later session's tool calls"

# ...and a fresh start for a NEW track must mint its own id, not inherit the stale one.
MB_ID2="$( cd "$MB_REPO" && PREFLIGHT_REQUIRE_GH=0 TRACK_ID=mb2 TRACK_BRANCH=docs/unrelated \
           bash .github/hooks/track-preflight.sh --persist --yes 2>/dev/null )"
[ -n "$MB_ID2" ] && [ "$MB_ID2" != "$MB_ID" ] \
  && pass "runid-block: a new track does not inherit the leftover block's run id" \
  || fail "runid-block: a new track does not inherit the leftover block's run id (got '$MB_ID2')"

# --complete still removes the block outright (unchanged contract).
( cd "$MB_REPO" && PREFLIGHT_REQUIRE_GH=0 TRACK_ID=mb2 TRACK_BRANCH=docs/unrelated \
  bash .github/hooks/track-preflight.sh --complete >/dev/null 2>&1 ) || true
grep -q 'track-preflight RUN_ID (managed' "$MB_ENV" 2>/dev/null \
  && fail "runid-block: --complete still retires the block" \
  || pass "runid-block: --complete still retires the block"

# Reconcile ranks candidates instead of taking the newest: the breadcrumb for the branch
# actually checked out here beats a newer one belonging to another branch.
( cd "$MB_REPO" && git checkout -q feat/mb )
mb_rec="$( cd "$MB_REPO" && printf '{}' | PREFLIGHT_REQUIRE_GH=0 bash .github/hooks/track-reconcile.sh 2>/dev/null || true )"
[ "$(printf '%s' "$mb_rec" | jq -r '.run_id // empty' 2>/dev/null)" = "$MB_ID" ] \
  && pass "reconcile: adopts the breadcrumb for the CHECKED-OUT branch, not the newest" \
  || fail "reconcile: adopts the breadcrumb for the CHECKED-OUT branch, not the newest"

rm -rf "$MB_REPO"

# ---------------------------------------------------------------------------
# SUITE 10b -- track-report.sh (deterministic PR-body Auto block)
# ---------------------------------------------------------------------------
section "track-report.sh"
REPORT="$SCRIPTS_DIR/track-report.sh"
[ -x "$REPORT" ] || chmod +x "$REPORT"

# Build a throwaway git repo + populated run record so the report has real diff + record.
RPT_REPO="$(mktemp -d)"
(
  cd "$RPT_REPO" && git init -q && git config user.email t@t && git config user.name t
  echo hi > a.go && git add a.go && git commit -q -m init
  echo more >> a.go && echo new > b.py && git add -A && git commit -q -m work
  mkdir -p runs
  RID="2026-01-02T03-04_setup"
  printf '{"run_id":"%s","branch":"feat-x","tasks":"T1-T3","created_utc":"2026-01-02T03:00:00Z","completed_utc":"2026-01-02T03:48:00Z","duration_secs":2880}\n' "$RID" > "runs/$RID.dispatch"
  cat > "runs/$RID.json" <<JSON
{"run_id":"$RID","v":1,"tool_calls":42,"started_ts":"2026-01-02T03:00:05Z","last_ts":"2026-01-02T03:47:55Z","iterations":3,
 "trace":[{"t":"2026-01-02T03:05Z","kind":"subagent","event":"SubagentStart","agent_id":"s1","agent_type":"Explore"}],
 "skills":[{"t":"2026-01-02T03:01Z","skill":"sso-single-branch-development","step":"scaffold","self_reported":true}],
 "evidence":[{"kind":"go-test","cmd":"go test ./...","response":"ok pkg","fingerprint":"abc123def456ghi"},{"kind":"py","cmd":"uv run pytest","response":"1 failed\nAssertionError","fingerprint":"abc123def456ghi"}]}
JSON
)
RID="2026-01-02T03-04_setup"
RPT_MD="$(cd "$RPT_REPO" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" "$RID" 2>&1 || true)"

# 10b.1 — renders without a printf/jq error
printf '%s' "$RPT_MD" | grep -qiE 'invalid option|usage: printf|jq: error' \
  && fail "report: renders clean (no printf/jq errors)" \
  || pass "report: renders clean (no printf/jq errors)"

# 10b.2 — changed files come from the DIFF (a.go modified, b.py added)
if printf '%s' "$RPT_MD" | grep -q 'a.go' && printf '%s' "$RPT_MD" | grep -q 'b.py'; then
  pass "report: files-changed table rendered from git diff"
else
  fail "report: files-changed table rendered from git diff"
fi

# 10b.3 — evidence pass/fail derived from recorded response text
if printf '%s' "$RPT_MD" | grep -qE 'go-test.*pass' && printf '%s' "$RPT_MD" | grep -qE 'py.*FAIL'; then
  pass "report: evidence pass/fail derived from record response"
else
  fail "report: evidence pass/fail derived from record response"
fi

# 10b.4 — mechanical tool_calls surfaced from the record
printf '%s' "$RPT_MD" | grep -q 'Tool calls:.*42' \
  && pass "report: tool_calls surfaced from record" \
  || fail "report: tool_calls surfaced from record"

# 10b.5 — self-reported skills/iterations fenced UNDER a self-reported heading
if printf '%s' "$RPT_MD" | grep -qi 'self-reported' \
   && printf '%s' "$RPT_MD" | grep -q 'Iterations.*3'; then
  pass "report: self-reported trace clearly labelled + separated"
else
  fail "report: self-reported trace clearly labelled + separated"
fi

# 10b.6 — RUN_ID recovered from the newest breadcrumb when none supplied
RPT_REC="$(cd "$RPT_REPO" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" 2>&1 || true)"
printf '%s' "$RPT_REC" | grep -q "$RID" \
  && pass "report: recovers RUN_ID from newest breadcrumb" \
  || fail "report: recovers RUN_ID from newest breadcrumb"

# 10b.7 — --json emits valid JSON carrying the same facts
RPT_JSON="$(cd "$RPT_REPO" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" --json "$RID" 2>/dev/null || true)"
if printf '%s' "$RPT_JSON" | jq -e '.tool_calls == 42 and (.evidence | length) == 2' >/dev/null 2>&1; then
  pass "report: --json is valid + carries the same facts"
else
  fail "report: --json is valid + carries the same facts"
fi

# 10b.8 — read-only: the record is byte-identical after reporting
if cmp -s "$RPT_REPO/runs/$RID.json" "$RPT_REPO/runs/$RID.json"; then
  RPT_BEFORE="$(cat "$RPT_REPO/runs/$RID.json")"
  (cd "$RPT_REPO" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" "$RID" >/dev/null 2>&1 || true)
  [ "$(cat "$RPT_REPO/runs/$RID.json")" = "$RPT_BEFORE" ] \
    && pass "report: read-only (never mutates the run record)" \
    || fail "report: read-only (never mutates the run record)"
fi
rm -rf "$RPT_REPO"

# 10b.9/10 — compliance warnings surface silent omissions (empty evidence / no review)
RPT_W="$(mktemp -d)"
(
  cd "$RPT_W" && git init -q && git config user.email t@t && git config user.name t
  echo x > f.txt && git add f.txt && git commit -q -m init
  mkdir -p runs
  # (a) bare record: no evidence, no code-review activation -> BOTH warnings fire
  printf '{"run_id":"R-bare"}\n' > runs/R-bare.dispatch
  printf '{"run_id":"R-bare","v":1,"tool_calls":1,"evidence":[],"skills":[]}\n' > runs/R-bare.json
  # (b) complete record: evidence + a requesting-code-review activation -> NO warnings
  printf '{"run_id":"R-ok"}\n' > runs/R-ok.dispatch
  cat > runs/R-ok.json <<JSON
{"run_id":"R-ok","v":1,"tool_calls":1,
 "evidence":[{"kind":"go-test","cmd":"go test ./...","response":"ok","fingerprint":"f1"}],
 "skills":[{"t":"t","skill":"requesting-code-review","step":"review","self_reported":true}]}
JSON
)
W_BARE="$(cd "$RPT_W" && TRACK_BASE_REF=HEAD RUNS_DIR=runs bash "$REPORT" R-bare 2>&1 || true)"
W_BARE_J="$(cd "$RPT_W" && RUNS_DIR=runs bash "$REPORT" --json R-bare 2>/dev/null || true)"
W_OK="$(cd "$RPT_W" && TRACK_BASE_REF=HEAD RUNS_DIR=runs bash "$REPORT" R-ok 2>&1 || true)"

# 10b.9 — bare record warns about BOTH missing evidence and missing review
if printf '%s' "$W_BARE" | grep -qi 'Compliance warnings' \
   && printf '%s' "$W_BARE" | grep -qi 'evidence gate ran on an empty pack' \
   && printf '%s' "$W_BARE" | grep -qi 'may have been skipped'; then
  pass "report: flags empty evidence + missing review as compliance warnings"
else
  fail "report: flags empty evidence + missing review as compliance warnings"
fi

# 10b.9b — --json exposes the warnings[] array
if printf '%s' "$W_BARE_J" | jq -e '(.warnings | length) == 2' >/dev/null 2>&1; then
  pass "report: --json exposes warnings[] array"
else
  fail "report: --json exposes warnings[] array"
fi

# 10b.10 — a record WITH review activation + evidence produces NO warnings
if printf '%s' "$W_OK" | grep -qi 'A code-review activation and at least one evidence row' \
   && ! printf '%s' "$W_OK" | grep -qi 'may have been skipped'; then
  pass "report: no compliance warnings when review + evidence are on record"
else
  fail "report: no compliance warnings when review + evidence are on record"
fi
rm -rf "$RPT_W"

# 10b.13 — the PR body carries the DISCIPLINE AUDIT.
# The point of the audit is that a REVIEWER sees it. A gate whose result only ever
# appeared in the author's terminal is one the reviewer has to take on trust.
RPT_A="$(mktemp -d)"
printf '# bundle\n' > "$RPT_A/gov.md"
_gsha="$( { if command -v shasum >/dev/null 2>&1; then shasum "$RPT_A/gov.md"; else sha1sum "$RPT_A/gov.md"; fi; } | cut -d' ' -f1)"
jq -nc --arg g "$RPT_A/gov.md" --arg s "$_gsha" \
  '{run_id:"rpta", v:1, tool_calls:3,
    phase:{mode:"story", step:"green"},
    phase_log:[{t:"2026-01-01T00:00:00Z",mode:"story",step:"governance"}],
    governance_bundle:{path:$g, sha:$s, t:"2026-01-01T00:00:00Z"},
    trace:[{t:"2026-01-01T01:00:00Z",kind:"subagent",event:"start",agent_id:"a1"}],
    evidence:[{t:"x",kind:"go",cmd:"go test",response:"ok",fingerprint:"f1"}]}' \
  > "$RPT_A/rpta.json"
A_OUT="$(RUN_ID=rpta RUNS_DIR="$RPT_A" bash "$REPORT" 2>/dev/null || true)"

printf '%s' "$A_OUT" | grep -q 'Discipline audit' \
  && pass "report: PR body includes a Discipline audit section" \
  || fail "report: PR body includes a Discipline audit section"

# Every finding must carry its remediation — a finding with no next step is noise
# a reviewer scrolls past.
if printf '%s' "$A_OUT" | grep -q 'How to clear it' \
   && printf '%s' "$A_OUT" | grep -q 'track-note.sh phase'; then
  pass "report: audit findings render with remediation"
else
  fail "report: audit findings render with remediation"
fi

# The honesty rule must survive into the PR: never let a green audit read as full proof.
# The scope limit has to be VISIBLE — a caveat only reachable by expanding a <details> is a
# caveat most reviewers never see, so assert both the inline line and the expandable list.
if printf '%s' "$A_OUT" | grep -q 'NOT checked mechanically' \
   && printf '%s' "$A_OUT" | grep -q 'necessary, not sufficient'; then
  pass "report: PR body states what the audit did NOT check"
else
  fail "report: PR body states what the audit did NOT check"
fi

# The inline caveat must sit OUTSIDE the collapsed block (i.e. before <details> opens).
# Heading-level-agnostic: this asserts WHERE the caveat sits, not how deep the section is
# nested, and the audit has been promoted from `####` to `###` once already.
_inline="$(printf '%s' "$A_OUT" | sed -n '/^#\{2,\} Discipline audit/,/<details>/p')"
if printf '%s' "$_inline" | grep -q 'Not a clean bill of health'; then
  pass "report: audit scope limit is stated inline, not hidden behind <details>"
else
  fail "report: audit scope limit is stated inline, not hidden behind <details>"
fi

# Not every PASS row is equally strong: phase/status rows read stamps the model wrote
# itself. Saying so keeps the table from reading as one uniform grade of proof.
if printf '%s' "$A_OUT" | grep -q 'stamps the model wrote itself'; then
  pass "report: distinguishes artifact-derived checks from self-reported ones"
else
  fail "report: distinguishes artifact-derived checks from self-reported ones"
fi

# Markdown safety: a remediation containing a pipe must not break the table.
if printf '%s' "$A_OUT" | grep -q 'success\\|blocked' \
   && ! printf '%s' "$A_OUT" | grep -q 'success\\\\|blocked'; then
  pass "report: pipes inside audit cells are escaped exactly once"
else
  fail "report: pipes inside audit cells are escaped exactly once"
fi

# track-report.sh must stay READ-ONLY even though it now shells out to the audit.
_before_a="$(md5 -q "$RPT_A/rpta.json" 2>/dev/null || md5sum "$RPT_A/rpta.json" | cut -d' ' -f1)"
RUN_ID=rpta RUNS_DIR="$RPT_A" bash "$REPORT" >/dev/null 2>&1 || true
_after_a="$(md5 -q "$RPT_A/rpta.json" 2>/dev/null || md5sum "$RPT_A/rpta.json" | cut -d' ' -f1)"
[ "$_before_a" = "$_after_a" ] \
  && pass "report: embedding the audit keeps track-report.sh read-only" \
  || fail "report: embedding the audit keeps track-report.sh read-only"

# A failing audit must NOT break report rendering — the report is a reporter, not a gate.
jq 'del(.governance_bundle)' "$RPT_A/rpta.json" > "$RPT_A/t2" && mv "$RPT_A/t2" "$RPT_A/rpta.json"
A_FAIL_OUT="$(RUN_ID=rpta RUNS_DIR="$RPT_A" bash "$REPORT" 2>/dev/null || true)"
if printf '%s' "$A_FAIL_OUT" | grep -q 'blocking'; then
  pass "report: a FAILING audit renders as a blocking notice, not a crash"
else
  fail "report: a FAILING audit renders as a blocking notice (got: $(printf '%s' "$A_FAIL_OUT" | grep -A1 'Discipline audit' | tail -1 | head -c 100))"
fi
rm -rf "$RPT_A"

# 10b.11/12 — files-changed grouping: many files → area summary + collapsible list;
#             few files → a plain per-file table (no <details>).
RPT_G="$(mktemp -d)"
(
  cd "$RPT_G" && git init -q && git config user.email t@t && git config user.name t
  git commit -q --allow-empty -m base
  # 15 files across 3 areas (> default threshold of 12) → grouped
  for d in alpha beta gamma; do
    mkdir -p "$d"
    for i in 1 2 3 4 5; do echo x > "$d/f$i.txt"; done
  done
  git add -A && git commit -q -m many
)
RPT_MANY="$(cd "$RPT_G" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" R-none 2>&1 || true)"

# 10b.11 — area summary table present, with per-area counts, + a collapsible full list
if printf '%s' "$RPT_MANY" | grep -qE '\| Area \| Files \| Changes \|' \
   && printf '%s' "$RPT_MANY" | grep -qE '`alpha/` \| 5' \
   && printf '%s' "$RPT_MANY" | grep -qi '<details><summary>All 15 files'; then
  pass "report: many files grouped by area + collapsible full list"
else
  fail "report: many files grouped by area + collapsible full list"
fi

# 10b.12 — a small diff stays a plain per-file table (no area grouping, no <details>)
(
  cd "$RPT_G" && echo y > alpha/f1.txt && git add -A && git commit -q -m small
)
RPT_FEW="$(cd "$RPT_G" && TRACK_BASE_REF=HEAD~1 RUNS_DIR=runs bash "$REPORT" R-none 2>&1 || true)"
if printf '%s' "$RPT_FEW" | grep -qE '\| File \| Change \|' \
   && ! printf '%s' "$RPT_FEW" | grep -qi '<details'; then
  pass "report: small diff renders a plain per-file table (no grouping)"
else
  fail "report: small diff renders a plain per-file table (no grouping)"
fi
rm -rf "$RPT_G"

# ---------------------------------------------------------------------------
# SUITE 11 -- SKILL.md + track-hooks.json structural integrity
# ---------------------------------------------------------------------------
section "SKILL.md + hooks structural integrity"
SKILL_MD="$SCRIPT_DIR/../SKILL.md"
HOOKS_JSON="$SCRIPT_DIR/../templates/track-hooks.json"

# 10.1 — all expected scripts exist
EXPECTED_SCRIPTS=(
  track-guard.sh track-preflight.sh track-reconcile.sh
  track-evidence.sh track-evidence-gate.sh
  track-meter.sh track-trace.sh track-sentinel.sh track-notify.sh track-report.sh
  track-deps.sh track-compact.sh track-brief.sh track-note.sh track-audit.sh
)
_all_exist=1
for _s in "${EXPECTED_SCRIPTS[@]}"; do
  [ -f "$SCRIPTS_DIR/$_s" ] || { _all_exist=0; break; }
done
[ "$_all_exist" -eq 1 ] \
  && pass "struct: all bundled scripts exist in scripts/" \
  || fail "struct: all bundled scripts exist in scripts/"

# 10.2 — track-hooks.json is valid JSON
jq empty "$HOOKS_JSON" 2>/dev/null \
  && pass "struct: track-hooks.json is valid JSON" \
  || fail "struct: track-hooks.json is valid JSON"

# 10.3 — preToolUse wires track-guard.sh
jq -e '[.hooks.preToolUse[]?.bash] | map(test("track-guard")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: preToolUse -> track-guard.sh" \
  || fail "struct: preToolUse -> track-guard.sh"

# 10.4 — sessionStart wires track-reconcile.sh
jq -e '[.hooks.sessionStart[]?.bash] | map(test("track-reconcile")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: sessionStart -> track-reconcile.sh" \
  || fail "struct: sessionStart -> track-reconcile.sh"

# 10.5 — postToolUse wires both track-evidence.sh and track-meter.sh
jq -e '[.hooks.postToolUse[]?.bash] | map(test("track-evidence[^-]|track-evidence\\.")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: postToolUse -> track-evidence.sh" \
  || fail "struct: postToolUse -> track-evidence.sh"
jq -e '[.hooks.postToolUse[]?.bash] | map(test("track-meter")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: postToolUse -> track-meter.sh" \
  || fail "struct: postToolUse -> track-meter.sh"

# 10.6 — stop wires evidence-gate AND sentinel
jq -e '[.hooks.stop[]?.bash] | map(test("track-evidence-gate")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: stop -> track-evidence-gate.sh" \
  || fail "struct: stop -> track-evidence-gate.sh"
jq -e '[.hooks.stop[]?.bash] | map(test("track-sentinel")) | any' \
    "$HOOKS_JSON" >/dev/null 2>&1 \
  && pass "struct: stop -> track-sentinel.sh" \
  || fail "struct: stop -> track-sentinel.sh"

# 10.7 — evidence-gate fires before sentinel in stop array (order matters)
_gate_idx=$(jq '[.hooks.stop[]?.bash] | to_entries
  | map(select(.value | test("track-evidence-gate"))) | .[0].key // 99' \
  "$HOOKS_JSON" 2>/dev/null)
_sentinel_idx=$(jq '[.hooks.stop[]?.bash] | to_entries
  | map(select(.value | test("track-sentinel"))) | .[0].key // 99' \
  "$HOOKS_JSON" 2>/dev/null)
[ "${_gate_idx:-99}" -lt "${_sentinel_idx:-99}" ] 2>/dev/null \
  && pass "struct: stop order — evidence-gate before sentinel" \
  || fail "struct: stop order — evidence-gate before sentinel (gate=${_gate_idx} sentinel=${_sentinel_idx})"

# 10.8 — SKILL.md defines all 8 pipeline steps in order.
# Scoped to the "## Pipeline" section: other sections legitimately use numbered lists
# (the run ledger does), and an unscoped scan would match those and pass for the wrong
# reason — a green assertion that proves nothing is worse than no assertion.
_pipeline_start=$(grep -n '^## Pipeline' "$SKILL_MD" 2>/dev/null | head -1 | cut -d: -f1)
_pipeline_end=$(awk -v s="${_pipeline_start:-0}" 'NR>s && /^## / {print NR; exit}' "$SKILL_MD" 2>/dev/null)
if [ -n "$_pipeline_start" ] && [ -n "$_pipeline_end" ]; then
  _pipeline_body=$(sed -n "${_pipeline_start},${_pipeline_end}p" "$SKILL_MD")
  _steps_ok=1; _prev=0
  for _step in 1 2 3 4 5 6 7 8; do
    _ln=$(printf '%s\n' "$_pipeline_body" | grep -n "^${_step}\. \*\*" | head -1 | cut -d: -f1)
    if [ -z "$_ln" ] || [ "$_ln" -le "$_prev" ] 2>/dev/null; then _steps_ok=0; break; fi
    _prev=$_ln
  done
  [ "$_steps_ok" -eq 1 ] \
    && pass "struct: SKILL.md Pipeline defines Steps 1-8 in correct order" \
    || fail "struct: SKILL.md Pipeline defines Steps 1-8 in correct order (broke at step ${_step})"
else
  fail "struct: SKILL.md has a '## Pipeline' section"
fi

# 10.9 — Skill-per-step map references all required superpower skills
_REQUIRED_SKILLS=(
  "using-git-worktrees"
  "dispatching-parallel-agents"
  "requesting-code-review"
  "subagent-driven-development"
  "verification-before-completion"
)
_skills_ok=1
for _sk in "${_REQUIRED_SKILLS[@]}"; do
  grep -q "$_sk" "$SKILL_MD" 2>/dev/null || { _skills_ok=0; break; }
done
[ "$_skills_ok" -eq 1 ] \
  && pass "struct: SKILL.md references all required superpower skills" \
  || fail "struct: SKILL.md references all required superpower skills"

# 10.10 — Every script named in track-hooks.json exists in scripts/
_missing=0
while IFS= read -r _scr; do
  [ -z "$_scr" ] && continue
  [ -f "$SCRIPTS_DIR/$_scr" ] || _missing=$((_missing+1))
# Strip the path prefix AND any trailing arguments — a wiring entry is a command line
# ("…/track-audit.sh --hook"), not a bare filename.
done < <(jq -r '.. | strings | select(test("track-.*\\.sh")) | gsub(".*/"; "") | split(" ")[0]' "$HOOKS_JSON" 2>/dev/null | sort -u)
[ "$_missing" -eq 0 ] \
  && pass "struct: all scripts in track-hooks.json exist in scripts/" \
  || fail "struct: $_missing scripts in track-hooks.json missing from scripts/"

# 10.11 — pr-body template exists and defines the two-zone (Auto / Asserted) contract
PR_BODY_TMPL="$SCRIPT_DIR/../templates/pr-body.md"
if [ -f "$PR_BODY_TMPL" ] \
   && grep -q '{{AUTO_BLOCK}}' "$PR_BODY_TMPL" \
   && grep -qi 'Asserted' "$PR_BODY_TMPL"; then
  pass "struct: templates/pr-body.md defines Auto + Asserted zones"
else
  fail "struct: templates/pr-body.md defines Auto + Asserted zones"
fi

# 10.12 — SKILL.md Step 8 wires the report script + pr-body template
if grep -q 'track-report.sh' "$SKILL_MD" 2>/dev/null \
   && grep -q 'templates/pr-body.md' "$SKILL_MD" 2>/dev/null; then
  pass "struct: SKILL.md Step 8 references track-report.sh + pr-body.md"
else
  fail "struct: SKILL.md Step 8 references track-report.sh + pr-body.md"
fi

# 10.13 — scaffold-mode.md guards against speculative structure (the .gitkeep-sprawl fix)
SCAFFOLD_MD="$SCRIPT_DIR/../references/scaffold-mode.md"
if grep -qi 'speculative structure' "$SCAFFOLD_MD" 2>/dev/null \
   && grep -qi 'task-declared surface' "$SCAFFOLD_MD" 2>/dev/null \
   && grep -qi '\.gitkeep' "$SCAFFOLD_MD" 2>/dev/null; then
  pass "struct: scaffold-mode.md guards against speculative structure / .gitkeep sprawl"
else
  fail "struct: scaffold-mode.md guards against speculative structure / .gitkeep sprawl"
fi

# 10.14 — SKILL.md gotchas cover speculative-structure + report-from-output
if grep -qi 'no speculative structure' "$SKILL_MD" 2>/dev/null \
   && grep -qi 'Report state from command output' "$SKILL_MD" 2>/dev/null; then
  pass "struct: SKILL.md gotchas cover speculative-structure + narration-before-action"
else
  fail "struct: SKILL.md gotchas cover speculative-structure + narration-before-action"
fi

# 10.15 — SKILL.md Step 8 wires the compliance-warnings gate
if grep -qi 'Compliance warnings' "$SKILL_MD" 2>/dev/null; then
  pass "struct: SKILL.md Step 8 wires the compliance-warnings check"
else
  fail "struct: SKILL.md Step 8 wires the compliance-warnings check"
fi

# 10.16 — pr-body.md steers the Asserted zone toward tables (Task→files→intent + compliance)
if grep -qi 'Task | Files' "$PR_BODY_TMPL" 2>/dev/null \
   && grep -qi 'What it adds' "$PR_BODY_TMPL" 2>/dev/null \
   && grep -qi 'How it.s enforced' "$PR_BODY_TMPL" 2>/dev/null \
   && grep -qi 'NEVER escaped' "$PR_BODY_TMPL" 2>/dev/null; then
  pass "struct: pr-body.md steers Asserted zone to tables (Task→files→intent) + warns vs escaped backticks"
else
  fail "struct: pr-body.md steers Asserted zone to tables (Task→files→intent) + warns vs escaped backticks"
fi

# 10.18 — pr-body.md keeps evidence canonical in the auto block; Asserted Verification is fallback-only
if grep -qi 'Evidence has ONE canonical home' "$PR_BODY_TMPL" 2>/dev/null \
   && grep -qi 'Check | Command | Result' "$PR_BODY_TMPL" 2>/dev/null \
   && grep -qi 'ONLY when the auto block shows' "$PR_BODY_TMPL" 2>/dev/null; then
  pass "struct: pr-body.md keeps evidence canonical in auto block, Asserted Verification is fallback-only"
else
  fail "struct: pr-body.md keeps evidence canonical in auto block, Asserted Verification is fallback-only"
fi

# 10.17 — governance is pushed to the MAKER (fan-out), not only the checker/review
STORY_MD="$SCRIPT_DIR/../references/story-mode.md"
REFACTOR_MD="$SCRIPT_DIR/../references/refactor-mode.md"
GOVERNANCE_MD="$SCRIPT_DIR/../references/governance.md"
if grep -qi 'maker. obligation' "$SKILL_MD" 2>/dev/null \
   && grep -qi 'governance bundle' "$SCAFFOLD_MD" 2>/dev/null \
   && grep -qi 'governance bundle' "$STORY_MD" 2>/dev/null \
   && grep -qi 'governance bundle' "$REFACTOR_MD" 2>/dev/null; then
  pass "struct: governance brief pushed to fan-out makers in all three cores"
else
  fail "struct: governance brief pushed to fan-out makers in all three cores"
fi

# 10.19 — the governance bundle is PERSISTED, not just held in context.
# This is the compaction fix: a bundle that lives only in the conversation is gone after
# a compaction, and the model then briefs subagents with filenames while believing it
# complied. Assert the reference exists and that all three cores point at the file.
if [ -f "$GOVERNANCE_MD" ] \
   && grep -q 'runs/<RUN_ID>.governance.md' "$GOVERNANCE_MD" 2>/dev/null \
   && grep -q 'track-note.sh governance' "$GOVERNANCE_MD" 2>/dev/null \
   && grep -q 'runs/<RUN_ID>.governance.md' "$SKILL_MD" 2>/dev/null; then
  pass "struct: governance bundle is persisted to runs/<RUN_ID>.governance.md + pinned"
else
  fail "struct: governance bundle is persisted to runs/<RUN_ID>.governance.md + pinned"
fi
_gov_refs=1
for _md in "$STORY_MD" "$REFACTOR_MD"; do
  grep -q 'runs/<RUN_ID>.governance.md' "$_md" 2>/dev/null || _gov_refs=0
done
[ "$_gov_refs" -eq 1 ] \
  && pass "struct: story + refactor cores re-read the bundle from disk, not memory" \
  || fail "struct: story + refactor cores re-read the bundle from disk, not memory"

# 10.20 — compaction discipline: run ledger + mandatory phase stamping + re-anchor
if grep -qi '^## Run Ledger' "$SKILL_MD" 2>/dev/null \
   && grep -qi 'compact' "$SKILL_MD" 2>/dev/null \
   && grep -q 'track-note.sh' "$SKILL_MD" 2>/dev/null \
   && grep -qi 'phase <mode> <step>' "$SKILL_MD" 2>/dev/null; then
  pass "struct: SKILL.md has a run ledger + compaction re-anchor + phase stamping"
else
  fail "struct: SKILL.md has a run ledger + compaction re-anchor + phase stamping"
fi

# 10.21 — terminal states are named, and only `success` may open a PR
if grep -qi '^## Terminal States' "$SKILL_MD" 2>/dev/null \
   && grep -q 'no-progress' "$SKILL_MD" 2>/dev/null \
   && grep -q 'budget-exceeded' "$SKILL_MD" 2>/dev/null \
   && grep -qi 'Only .success. opens a PR' "$SKILL_MD" 2>/dev/null; then
  pass "struct: SKILL.md names all four terminal states + gates the PR on success"
else
  fail "struct: SKILL.md names all four terminal states + gates the PR on success"
fi

# 10.22 — scaffold mode reviews BEFORE it verifies.
# The convergence gate needs every evidence kind captured against ONE final tree, so a
# review-driven fix after the capture invalidates it. Verifying first guarantees paying
# that cost on every finding — this asserts scaffold matches the universal bracket order.
_review_idx=$(grep -n 'REVIEW GATE' "$SCAFFOLD_MD" 2>/dev/null | head -1 | cut -d: -f1)
_verify_idx=$(grep -n 'CONVERGENCE' "$SCAFFOLD_MD" 2>/dev/null | head -1 | cut -d: -f1)
if [ -n "$_review_idx" ] && [ -n "$_verify_idx" ] && [ "$_review_idx" -lt "$_verify_idx" ] 2>/dev/null; then
  pass "struct: scaffold-mode review gate precedes the convergence gate"
else
  fail "struct: scaffold-mode review gate precedes the convergence gate (review=${_review_idx} verify=${_verify_idx})"
fi

# 10.23 — no cross-document numeric step references.
# SKILL.md numbers 1-8; each mode reference numbers its own core. A bare "Step 5" means
# different things in the two files, which is how a step gets skipped. Mode references
# must cite NAMED gates only.
_numeric=0
for _md in "$SCAFFOLD_MD" "$STORY_MD" "$REFACTOR_MD"; do
  grep -qE 'Step[- ][0-9]|Steps [0-9]' "$_md" 2>/dev/null && _numeric=$((_numeric+1))
done
[ "$_numeric" -eq 0 ] \
  && pass "struct: mode references cite named gates, not cross-document step numbers" \
  || fail "struct: $_numeric mode reference(s) still cite numeric steps"

# 10.24 — the self-heal cap has a durable home (survives a context compaction)
ENV_TMPL="$SCRIPT_DIR/../templates/track-env.sh.example"
if grep -q 'TRACK_SELF_HEAL_ATTEMPTS' "$ENV_TMPL" 2>/dev/null \
   && grep -q 'TRACK_MAX_TOKEN_ESTIMATE' "$ENV_TMPL" 2>/dev/null \
   && grep -q 'TRACK_SELF_HEAL_ATTEMPTS' "$SKILL_MD" 2>/dev/null; then
  pass "struct: self-heal cap + token ceiling live in the env preset, not only in prose"
else
  fail "struct: self-heal cap + token ceiling live in the env preset, not only in prose"
fi

# 10.24b — the stale-run-state surfaces must stay documented where an operator looks.
# The escape hatch and the self-retirement rule are only useful if they are findable: the
# reported failure cost a full session to diagnose because the three gates trip together
# and read as one policy, while the guard's scope is not keyed to RUN_ID at all.
HOOKS_MD="$SCRIPT_DIR/../references/hooks.md"
if grep -q 'TRACK_EVIDENCE_SKIP_GLOBS' "$ENV_TMPL" 2>/dev/null \
   && grep -q 'TRACK_EVIDENCE_SKIP_GLOBS' "$HOOKS_MD" 2>/dev/null \
   && grep -q 'TRACK_EVIDENCE_SKIP_GLOBS' "$SCRIPTS_DIR/install-hooks.sh" 2>/dev/null; then
  pass "struct: docs-only evidence escape is documented in preset + reference + installer"
else
  fail "struct: docs-only evidence escape is documented in preset + reference + installer"
fi
if grep -qi 'self-retiring' "$HOOKS_MD" 2>/dev/null \
   && grep -qi 'self-retiring' "$ENV_TMPL" 2>/dev/null \
   && grep -qiE 'Triage: a hook is blocking' "$HOOKS_MD" 2>/dev/null; then
  pass "struct: RUN_ID self-retirement + a blocking-hook triage path are documented"
else
  fail "struct: RUN_ID self-retirement + a blocking-hook triage path are documented"
fi

# 10.24c — install.sh must not read `specify integration install`'s idempotent no-op as a
# successful pin. The CLI exits 0 and prints "already installed / No files were changed"
# on a repo that already has the integration, so exit status alone reported a version pin
# as applied while the older bundle stayed on disk. Structural (running it needs uvx +
# network): assert the escalation to `upgrade` and the read-back verification both exist.
INSTALL_SH="$GIT_TOP/install.sh"
if grep -qiE 'already installed\|no files were changed' "$INSTALL_SH" 2>/dev/null \
   && grep -q 'specify integration upgrade' "$INSTALL_SH" 2>/dev/null \
   && grep -q '.specify/integration.json' "$INSTALL_SH" 2>/dev/null; then
  pass "struct: install.sh detects specify's idempotent no-op and verifies the applied version"
else
  fail "struct: install.sh detects specify's idempotent no-op and verifies the applied version"
fi

# 10.26 — the audit is wired on BOTH surfaces and named in the pipeline.
# A checker nobody invokes is a document, which is the problem it was built to fix.
CLAUDE_TMPL="$SCRIPT_DIR/../templates/claude-settings.json"
_wired=1
jq -e '[.hooks.stop[]?.bash] | map(test("track-audit")) | any' "$HOOKS_JSON" >/dev/null 2>&1 || _wired=0
jq -e '[.hooks.Stop[]?.hooks[]?.command] | map(test("track-audit")) | any' "$CLAUDE_TMPL" >/dev/null 2>&1 || _wired=0
[ "$_wired" -eq 1 ] \
  && pass "struct: track-audit.sh wired into Stop on both Copilot and Claude Code" \
  || fail "struct: track-audit.sh wired into Stop on both Copilot and Claude Code"

# Both wirings must pass --hook: without it the script runs in CLI mode inside a hook,
# ignoring TRACK_AUDIT and never emitting the block contract.
_hookflag=1
jq -e '[.hooks.stop[]?.bash] | map(select(test("track-audit"))) | all(test("--hook"))' "$HOOKS_JSON" >/dev/null 2>&1 || _hookflag=0
jq -e '[.hooks.Stop[]?.hooks[]?.command] | map(select(test("track-audit"))) | all(test("--hook"))' "$CLAUDE_TMPL" >/dev/null 2>&1 || _hookflag=0
[ "$_hookflag" -eq 1 ] \
  && pass "struct: both wirings invoke track-audit.sh with --hook" \
  || fail "struct: both wirings invoke track-audit.sh with --hook"

# 10.27 — the audit runs before the PR, and the checklist marks what it covers.
CHECKLIST="$SCRIPT_DIR/prompt-level-checklist.md"
if grep -q 'track-audit.sh' "$SKILL_MD" 2>/dev/null \
   && [ -f "$CHECKLIST" ] \
   && grep -q 'track-audit.sh' "$CHECKLIST" 2>/dev/null \
   && grep -q '⚙️' "$CHECKLIST" 2>/dev/null \
   && grep -q '✋' "$CHECKLIST" 2>/dev/null; then
  pass "struct: SKILL.md runs the audit; checklist marks automated vs human items"
else
  fail "struct: SKILL.md runs the audit; checklist marks automated vs human items"
fi

# 10.28 — the wholesale-skip gate lives OUTSIDE the agent.
# track-audit.sh catches a run that missed a step; it cannot catch a run that skipped the
# bundle, because then there is no record to audit and no Auto block to be missing from.
# A reporter cannot report on its own absence, so this check must be CI-side.
# NOTE: $REPO_ROOT resolves to .github/ (it is one level short — harmless for the git
# operations every other test uses, but wrong for a repo-relative path). Ask git.
GIT_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || echo "$REPO_ROOT/..")"
AGENT_WF="$GIT_ROOT/.github/workflows/agent-pr-audit.yml"
if [ -f "$AGENT_WF" ] \
   && grep -q 'END track-report auto block' "$AGENT_WF" \
   && grep -q 'agent-generated' "$AGENT_WF" \
   && grep -q 'blocking — this PR should not have been opened' "$AGENT_WF"; then
  pass "struct: CI gate asserts the Auto block + no blocking audit on agent PRs"
else
  fail "struct: CI gate asserts the Auto block + no blocking audit on agent PRs"
fi

# Scoped to agent PRs only. A blanket rule would fail every hand-written PR and be
# switched off within a week — a gate nobody can live with protects nothing.
if grep -q 'needs.detect.outputs.is_agent' "$AGENT_WF" 2>/dev/null \
   && grep -q 'AGENT_LABEL' "$AGENT_WF" 2>/dev/null; then
  pass "struct: CI gate is scoped to agent PRs (human PRs untouched)"
else
  fail "struct: CI gate is scoped to agent PRs (human PRs untouched)"
fi

# ...but NOT on a signal the agent applies to itself. The label is written by the agent at
# `gh pr create`, so a run that skipped the bundle also skips the labeling step and the PR
# most needing an audit is the one that opts itself out. Detection must include at least one
# signal produced OUTSIDE the skill — the harness-written Co-Authored-By commit trailer.
if grep -q 'Co-Authored-By' "$AGENT_WF" 2>/dev/null \
   && grep -q 'pulls/\$PR_NUM/commits' "$AGENT_WF" 2>/dev/null; then
  pass "struct: CI detection does not rely solely on the agent's self-applied label"
else
  fail "struct: CI detection does not rely solely on the agent's self-applied label"
fi

# Meta-work exemption: the repo that DEVELOPS the bundle cannot run the bundle's pipeline
# for its own maintenance, so tooling PRs would go permanently red — and an always-red check
# trains people to ignore it. The waiver must be narrow (all files tooling), fail closed (an
# unreadable file list exempts nothing), and announce itself instead of passing quietly.
if grep -q 'META_PATHS_RE' "$AGENT_WF" 2>/dev/null \
   && grep -q 'meta_only' "$AGENT_WF" 2>/dev/null \
   && grep -q 'GITHUB_STEP_SUMMARY' "$AGENT_WF" 2>/dev/null; then
  pass "struct: CI waives the Auto block for meta-work and logs the waiver"
else
  fail "struct: CI waives the Auto block for meta-work and logs the waiver"
fi

# The exemption must actually be reachable for the maintenance it exists to cover — and it
# must still stop at product code. A release PR is the sharp case: it MUST edit CHANGELOG.md
# and, like every meta PR, produces no run record — so omitting the changelog from
# META_PATHS_RE left release PRs able to satisfy neither the exemption nor the Auto-block
# requirement. An unsatisfiable rule gets bypassed rather than obeyed.
_meta_re="$(grep -m1 'META_PATHS_RE:' "$AGENT_WF" 2>/dev/null | sed "s/.*META_PATHS_RE: *//; s/^'//; s/'\$//")"
_meta_ok=1
for _p in CHANGELOG.md README.md install.sh .github/skills/x/SKILL.md .github/workflows/w.yml; do
  printf '%s' "$_p" | grep -qE "$_meta_re" || { _meta_ok=0; break; }
done
for _p in src/app.go backend-go/main.go deploy/docker-compose.yml; do
  printf '%s' "$_p" | grep -qE "$_meta_re" && { _meta_ok=0; break; }
done
[ "$_meta_ok" = "1" ] \
  && pass "struct: meta exemption covers release/docs tooling but never product code" \
  || fail "struct: meta exemption misclassifies a path (re: $_meta_re)"

# The waiver must cover PRESENCE only. If a block IS present it still goes through the
# consistency + no-blocking-failure checks, so a waived PR cannot smuggle a broken block.
if grep -qE 'META_ONLY.*=.*"true".*&&.*!.*grep -qF "\$marker"' "$AGENT_WF" 2>/dev/null; then
  pass "struct: the meta waiver applies only when no Auto block is present"
else
  fail "struct: the meta waiver applies only when no Auto block is present"
fi

# A waived PR that edits the gates themselves is changing the enforcement while exempt from
# it — the one abuse the exemption makes possible. It must be called out, not left implicit.
if grep -q 'GATE_PATHS_RE' "$AGENT_WF" 2>/dev/null \
   && grep -q 'modifies the enforcement itself' "$AGENT_WF" 2>/dev/null; then
  pass "struct: a waived PR touching the gates is flagged in the summary"
else
  fail "struct: a waived PR touching the gates is flagged in the summary"
fi

# GitHub runs every `run:` block as `bash -e`, and an in-script `set -uo pipefail` does NOT
# undo that. A grep that legitimately matches nothing — no audit section in the body, a clean
# audit with no rows — then aborts the step with a bare "exit code 1" instead of reporting the
# verdict it exists to report: the gate fails for the wrong reason and says nothing useful.
# Counting/extracting greps must therefore carry `|| true`. (`grep -q` in a condition is safe;
# set -e exempts the test of an `if`.) This is invisible until CI runs, so pin it here.
_bad_grep="$(grep -nE 'grep -(c|o)' "$AGENT_WF" 2>/dev/null | grep -v '|| true' || true)"
if [ -z "$_bad_grep" ]; then
  pass "struct: CI greps that may match nothing are guarded against bash -e"
else
  fail "struct: unguarded counting grep in the CI gate (bash -e aborts): $_bad_grep"
fi

# A hand-edited Auto block is the last way a failing audit reaches a reviewer looking clean:
# every non-PASS check renders exactly one table row, so the declared counts and the rendered
# rows must agree or the block was edited after it was generated.
if grep -q 'CONTRADICTS ITSELF' "$AGENT_WF" 2>/dev/null \
   && grep -q 'fail_rows' "$AGENT_WF" 2>/dev/null \
   && grep -q 'warn_rows' "$AGENT_WF" 2>/dev/null; then
  pass "struct: CI gate cross-checks the audit's declared counts against its rendered rows"
else
  fail "struct: CI gate cross-checks the audit's declared counts against its rendered rows"
fi

# The PR body is attacker-controlled text: it must reach the script through the
# environment, never via ${{ }} interpolation inside a run block (shell-injection sink).
# Same for the fork-chosen branch name and the detection summary derived from it.
if grep -q 'PR_BODY: \${{ github.event.pull_request.body }}' "$AGENT_WF" 2>/dev/null \
   && ! grep -E '^\s+(echo|printf|grep|if).*\$\{\{ *(github\.event\.pull_request\.(body|head\.ref|user)|needs\.detect\.outputs\.why)' "$AGENT_WF" >/dev/null 2>&1; then
  pass "struct: CI gate passes attacker-controlled values via env, not inline interpolation"
else
  fail "struct: CI gate passes attacker-controlled values via env, not inline interpolation"
fi

# A green audit must not read as a full bill of health. The count of items no machine checked
# has to be visible in the PR body itself, not folded away inside the collapsed <details>.
if grep -q 'Not a clean bill of health' "$REPORT" 2>/dev/null; then
  pass "struct: report states the audit's scope limit inline, outside the collapsed block"
else
  fail "struct: report states the audit's scope limit inline, outside the collapsed block"
fi

# The skill must actually attach the label the gate keys on, or the gate never fires.
grep -q 'agent-generated' "$SKILL_MD" 2>/dev/null \
  && pass "struct: SKILL.md labels the PR agent-generated so the CI gate fires" \
  || fail "struct: SKILL.md labels the PR agent-generated so the CI gate fires"

# 10.25 — SKILL.md body stays within the repo's own 500-line hard maximum
_skill_lines=$(wc -l < "$SKILL_MD" | tr -d ' ')
[ "$_skill_lines" -le 500 ] \
  && pass "struct: SKILL.md is ${_skill_lines} lines (<= 500 hard max)" \
  || fail "struct: SKILL.md is ${_skill_lines} lines (exceeds the 500-line hard max)"

# ---------------------------------------------------------------------------
# SUITE 14 -- track-deps.sh dependency version-lock + TTL probe cache
# ---------------------------------------------------------------------------
section "track-deps.sh version-lock + probe cache"
_DEPS_TMP="$(mktemp -d)"
_deps_manifest() { printf '%s' "$1" > "$_DEPS_TMP/$2"; printf '%s' "$_DEPS_TMP/$2"; }

# 14.1 — absent manifest is a silent no-op (exit 0, deps not configured)
_out=$(TRACK_DEPS_MANIFEST="$_DEPS_TMP/does-not-exist.json" RUNS_DIR="$_DEPS_TMP/r1" \
  bash "$DEPS" --json 2>/dev/null) && _rc=0 || _rc=$?
if [ "$_rc" -eq 0 ] && printf '%s' "$_out" | jq -e '.configured == false' >/dev/null 2>&1; then
  pass "deps: absent manifest is a no-op (exit 0, configured:false)"
else
  fail "deps: absent manifest is a no-op (rc=$_rc, out=$(printf '%s' "$_out" | head -c 80))"
fi

# 14.2 — all-present + in-range → ok, exit 0, and a cache file is written
_m=$(_deps_manifest '{"schema":1,"dependencies":{"git":{"range":">=2.0","probe":"git --version","required":true}}}' ok.json)
_r="$_DEPS_TMP/r2"
_out=$(TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_r" bash "$DEPS" --json 2>/dev/null) && _rc=0 || _rc=$?
if [ "$_rc" -eq 0 ] && printf '%s' "$_out" | jq -e '.ok == true' >/dev/null 2>&1 \
   && [ -f "$_r/.deps-cache.json" ]; then
  pass "deps: all-present in-range → ok exit 0 + cache written"
else
  fail "deps: all-present in-range (rc=$_rc, cache=$([ -f "$_r/.deps-cache.json" ] && echo y || echo n))"
fi

# 14.3 — second run is a cache hit (resolved_utc unchanged)
_first=$(jq -r '.resolved_utc' "$_r/.deps-cache.json" 2>/dev/null)
TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_r" bash "$DEPS" --verify >/dev/null 2>&1 || true
_second=$(jq -r '.resolved_utc' "$_r/.deps-cache.json" 2>/dev/null)
if [ -n "$_first" ] && [ "$_first" = "$_second" ]; then
  pass "deps: second run hits the cache (resolved_utc unchanged)"
else
  fail "deps: second run hits the cache (first=$_first second=$_second)"
fi

# 14.4 — --refresh ignores the cache and re-resolves (new resolved_utc allowed)
_out=$(TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_r" bash "$DEPS" --refresh --json 2>/dev/null) && _rc=0 || _rc=$?
if [ "$_rc" -eq 0 ] && printf '%s' "$_out" | jq -e '.ok == true and (.cached == false)' >/dev/null 2>&1; then
  pass "deps: --refresh bypasses the cache (cached:false)"
else
  fail "deps: --refresh bypasses the cache (rc=$_rc, out=$(printf '%s' "$_out" | head -c 80))"
fi

# 14.5 — a required tool that is missing → lock violation, exit 3
_m=$(_deps_manifest '{"schema":1,"dependencies":{"nosuchbin_zzz":{"range":">=1.0","probe":"nosuchbin_zzz --version","required":true}}}' miss.json)
TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_DEPS_TMP/r3" bash "$DEPS" --verify >/dev/null 2>&1 && _rc=0 || _rc=$?
[ "$_rc" -eq 3 ] \
  && pass "deps: required-missing tool → exit 3 (lock violation)" \
  || fail "deps: required-missing tool → exit 3 (got $_rc)"

# 14.6 — required-missing must NOT be cached (re-checked every run)
[ ! -f "$_DEPS_TMP/r3/.deps-cache.json" ] \
  && pass "deps: a failing result is not cached" \
  || fail "deps: a failing result is not cached (cache file present)"

# 14.7 — out-of-range, non-strict → warn only (exit 0, ok:true, warnings non-empty)
_m=$(_deps_manifest '{"schema":1,"dependencies":{"git":{"range":">=9999.0","probe":"git --version","required":true}}}' oor.json)
_out=$(TRACK_DEPS_STRICT=0 TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_DEPS_TMP/r4" bash "$DEPS" --json 2>/dev/null) && _rc=0 || _rc=$?
if [ "$_rc" -eq 0 ] && printf '%s' "$_out" | jq -e '.ok == true and ((.warnings|length) > 0)' >/dev/null 2>&1; then
  pass "deps: out-of-range non-strict → exit 0 + warning"
else
  fail "deps: out-of-range non-strict (rc=$_rc, out=$(printf '%s' "$_out" | head -c 100))"
fi

# 14.8 — out-of-range, strict → lock violation, exit 3
TRACK_DEPS_STRICT=1 TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_DEPS_TMP/r5" bash "$DEPS" --verify >/dev/null 2>&1 && _rc=0 || _rc=$?
[ "$_rc" -eq 3 ] \
  && pass "deps: out-of-range strict → exit 3 (lock violation)" \
  || fail "deps: out-of-range strict → exit 3 (got $_rc)"

# 14.9 — TTL=0 disables caching (in-range OK but no cache file written)
_m=$(_deps_manifest '{"schema":1,"dependencies":{"git":{"range":">=2.0","probe":"git --version","required":true}}}' ttl0.json)
_r="$_DEPS_TMP/r6"
TRACK_DEPS_CACHE_TTL_HOURS=0 TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_r" bash "$DEPS" --verify >/dev/null 2>&1 && _rc=0 || _rc=$?
if [ "$_rc" -eq 0 ] && [ ! -f "$_r/.deps-cache.json" ]; then
  pass "deps: TTL=0 disables the cache (no cache file)"
else
  fail "deps: TTL=0 disables the cache (rc=$_rc, cache=$([ -f "$_r/.deps-cache.json" ] && echo y || echo n))"
fi

# 14.10 — an optional (required:false) missing tool does NOT fail the lock
_m=$(_deps_manifest '{"schema":1,"dependencies":{"nosuchbin_zzz":{"range":"","probe":"nosuchbin_zzz --version","required":false}}}' opt.json)
TRACK_DEPS_MANIFEST="$_m" RUNS_DIR="$_DEPS_TMP/r7" bash "$DEPS" --verify >/dev/null 2>&1 \
  && pass "deps: optional missing tool → exit 0 (no lock violation)" \
  || fail "deps: optional missing tool → exit 0 (got non-zero)"

rm -rf "$_DEPS_TMP"

# ---------------------------------------------------------------------------
# Summary
# ---------------------------------------------------------------------------
TOTAL=$((PASS + FAIL + SKIP))
printf '\n===============================================\n'
printf '  sso-single-branch-development  test suite\n'
printf '  Date:   %s\n' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
printf '  Branch: %s\n' "$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo unknown)"
printf '  Total: %d   passed: %d   failed: %d   skipped: %d\n' \
  "$TOTAL" "$PASS" "$FAIL" "$SKIP"
printf '===============================================\n'
if [ "$FAIL" -gt 0 ]; then
  printf '\nFailed:\n%b\n' "$FAILURES"
  exit 1
fi
exit 0
